interface GridDefinition {
	numRows: number;
	numCols: number;
	isFirstRowFull: boolean;
}

export interface QueryOptions {
	/**
	 * Target team.
	 */
	team: Team;

	/**
	 * Disable a choice if it does not contain a creature matching the team argument.
	 */
	requireCreature: boolean;
	id: number;
	flipped: boolean;
	x: number;
	y: number;
	hexesDashed: Hex[];
	dashedHexesUnderCreature: boolean;
	fillOnlyHoveredCreature: boolean;
	shrunkenHexes: Hex[];
	hexesDeadZone: Hex[];
	directions: number[];
	includeCreature: boolean;
	stopOnCreature: boolean;
	pierceNumber: number;
	pierceThroughBehavior: string;

	/**
	 * If defined, maximum distance of query in hexes.
	 */
	distance: number;

	/**
	 * If defined, minimum distance of query, 1 = 1 hex gap required.
	 */
	minDistance: number;

	isDirectionsQuery: boolean;

	/**
	 * After this distance, the direction choice will be be visualised by shrunken hexes.
	 * This visual state represents the ability having its effectiveness being reduced
	 * in some way (falling off).
	 */
	distanceFalloff: number;

	/**
	 * If a choice line stops on a creature via @param stopOnCreature, display
	 * 	dashed hexes after the creature up until the next obstacle
	 */
	dashedHexesAfterCreatureStop: boolean;

	/**
	 * Limit the length of dashed hexes added by @param dashedHexesAfterCreatureStop
	 */
	dashedHexesDistance: number;

	sourceCreature: Creature;
	choices: Hex[][];

	/**
	 * Object given to the events function (to easily pass variables for these functions).
	 */
	arg: any;

	optTest: (arg: Creature) => boolean;
	ignoreCreatureTest?: (arg: Creature) => boolean;

	/**
	 * Function applied when clicking on one of the available hexes.
	 */
	fnOnSelect: () => void;

	/**
	 * Function applied when clicking again on the same hex.
	 */
	fnOnConfirm: () => void;

	/**
	 * Function applied when clicking a non reachable hex
	 */
	fnOnCancel: () => void;
}

/**
 * A `previewCreature` call parked while its unit cardboard downloads.
 */
interface PendingPreview {
	pos: { x: number; y: number };
	creatureData: any;
	player: any;
	secondary: boolean;
}

interface PendingPreviews {
	primary?: PendingPreview;
	secondary?: PendingPreview;
}

/**
 * Previews held back while a unit cardboard downloads, one slot per overlay.
 *
 * Keyed by grid rather than stored on it: `previewCreature` is also exercised
 * against stand-in grids, and per-overlay scratch state has no business on the
 * class surface.
 */
const pendingPreviews = new WeakMap<object, PendingPreviews>();

function getPendingPreviews(grid: object): PendingPreviews {
	let previews = pendingPreviews.get(grid);
	if (!previews) {
		previews = {};
		pendingPreviews.set(grid, previews);
	}
	return previews;
}

function setPendingPreview(
	grid: object,
	slot: keyof PendingPreviews,
	request: PendingPreview,
): void {
	getPendingPreviews(grid)[slot] = request;
}

function takePendingPreview(grid: object, slot: keyof PendingPreviews): PendingPreview | undefined {
	const request = getPendingPreviews(grid)[slot];
	if (request) {
		delete getPendingPreviews(grid)[slot];
	}
	return request;
}

function clearPendingPreview(grid: object, secondary: boolean): void {
	takePendingPreview(grid, secondary ? 'secondary' : 'primary');
}

/**
 * Redraw a preview that was waiting on its unit's cardboard.
 *
 * Takes the held request rather than a captured closure, so moving the cursor
 * while the texture was in flight supersedes the stale position instead of
 * painting a ghost on a hex the cursor has already left.
 */
function replayPendingPreview(grid: HexGrid, secondary: boolean): void {
	const pending = takePendingPreview(grid, secondary ? 'secondary' : 'primary');
	if (pending) {
		grid.previewCreature(pending.pos, pending.creatureData, pending.player, pending.secondary);
	}
}

/**
 * Drop every tween still bound to a preview overlay.
 *
 * The two ways a ghost is dismissed both fade it with a tween that nothing
 * tracks — `fadeOutTempCreature()` on materialization, and `Creature`'s move
 * handler on a move confirm. `previewCreature()` cannot reach either handle, so
 * the fade kept writing `alpha` every frame after the ghost had been handed
 * back: a ghost pinned afterwards was dragged straight back to 0 and only
 * reappeared once the stale tween finally ended, which is why the movement
 * preview (drawn from `Creature.tracePath()`) showed up late — or not at all,
 * when the next hover landed inside the same fade.
 */
function clearPreviewTweens(game: { gameEngine?: GameEngine }, overlay: any): void {
	if (overlay) {
		game.gameEngine?.removeTweensFrom?.(overlay);
	}
}

/**
 * Object containing grid and methods concerning the whole grid.
 * Should only have one instance during the game.
 */
/**
 * Bounds for a sprite that can still be measured, or `null`.
 *
 * A sprite whose texture has been unloaded — which is what teardown mid-hover
 * leaves behind — has a null frame, and Phaser's `getBounds()` then throws from
 * inside `realWidth` rather than returning anything. Hover/xray is cosmetic, so
 * an unmeasurable sprite is reported as unmeasurable instead of crashing the
 * xray pass. Checking `frame.source` catches the common case without relying on
 * Phaser throwing, and the catch covers the rest.
 */
function safeSpriteBounds(sprite: unknown): {
	left: number;
	right: number;
	top: number;
	bottom: number;
} | null {
	if (!sprite || typeof (sprite as { getBounds?: unknown }).getBounds !== 'function') return null;
	if (!(sprite as { frame?: { source?: unknown } }).frame?.source) return null;
	try {
		return (
			sprite as {
				getBounds: () => { left: number; right: number; top: number; bottom: number };
			}
		).getBounds();
	} catch {
		return null;
	}
}

export class HexGrid {
	game: Game;

	/**
	 * Contain all hexes in row arrays (hexes[y][x]).
	 */
	hexes: Hex[][];

	/**
	 * Last hex clicked!
	 */
	lastClickedHex: Hex;

	/**
	 * Prevents multiple shouts at the same time when a unit is clicked.
	 */
	onShoutCooldown: boolean;

	/**
	 * Last hovered creature.
	 */
	hoveredCreature: Creature | null = null;

	/**
	 * Last hex passed to xray(). Used to reapply the effect on tab focus.
	 */
	lastXrayHex: Hex | null = null;

	/**
	 * The hex the physical mouse pointer is currently over, updated before any
	 * freezedInput guard so it remains accurate during ability animations.
	 * Distinct from selectedHex which the keyboard cursor and queryHexes() reset.
	 *
	 * Backed by the input module rather than kept as a field of its own: the
	 * module is the single owner of pointer position, and a second copy here
	 * would be free to disagree with it.
	 */
	get lastMouseHex(): Hex | undefined {
		return getHoveredHex() as Hex | undefined;
	}

	set lastMouseHex(hex: Hex | undefined) {
		setHoveredHex(hex);
	}

	/**
	 * True while refreshHoverState() is replaying hover behavior programmatically.
	 * Used to avoid recursive query rebuilds caused by movement hover callbacks.
	 */
	isRefreshingHoverState = false;

	/**
	 * One-shot guard used to skip the next hover replay after a turn handoff.
	 */
	suppressNextHoverRefresh = false;

	/**
	 * Deferred clear for active-creature dashed hex visuals. This avoids
	 * toggling dashed->normal->dashed while the cursor crosses adjacent hexes.
	 */
	activeHexDashedClearTimeout: ReturnType<typeof setTimeout> | null = null;

	display: any;
	gridGroup: any;
	trapGroup: any;
	hexesGroup: any;
	displayHexesGroup: any;
	overlayHexesGroup: any;
	dropGroup: any;
	creatureGroup: any;
	/**
	 * A sibling of {@link creatureGroup} holding Infernal's smoke. Smoke is
	 * deliberately not parented to the cardboard: a child of the moving group is
	 * dragged along by the group's position tween, so it slides with the unit
	 * instead of hanging in the air where it was released. Here it stays put and
	 * the unit walks out from under it.
	 */
	infernalSmokeGroup: any;
	healthIndicatorUiGroup: any;
	trapOverGroup: any;
	selectedHex: Hex;
	_executionMode: boolean;
	materialize_overlay: any;
	secondary_overlay: any;
	lastQueryOpt: any;

	/**
	 * Bumped by every *fresh* query installed through queryHexes() — a redo of
	 * the current query (`redoLastQuery()`) leaves it alone, since re-running the
	 * same query is not a new claim on the board.
	 *
	 * Work that opens a turn defers its own queryMove() so the activation
	 * animation plays first, and that query is stale the moment the player or a
	 * bot takes the board in the meantime. Snapshotting this counter lets the
	 * deferred work notice the takeover and stay out of the way instead of
	 * replacing the live query.
	 */
	queryGeneration = 0;

	/**
	 * Helper to determine cursor style for multiplayer games.
	 * When it's not the local player's turn, returns 'wait' instead of the normal cursor.
	 * @param normalCursor The cursor to show when it's the local player's turn
	 * @returns 'wait' if opponent's turn, otherwise the normal cursor
	 */
	private getCursorForMultiplayer(normalCursor: string): string {
		const isLocalPlayerTurn = !this.game.multiplayer || this.game.lobby?.isMyTurn();
		return isLocalPlayerTurn ? normalCursor : 'wait';
	}

	/** Memoised backing store for {@link allhexes}. See the getter for why. */
	private _allhexes: Hex[] | null = null;

	/**
	 * Every hex in the grid, row-major.
	 *
	 * Memoised: this used to be `this.hexes.flat(1)`, which rebuilt a fresh
	 * ~130-element array on *every* read. `allhexes` is read at 100 Hz by the UI
	 * glow interval and several more times per hex hover, so that was tens of
	 * thousands of pointless element copies per second. The grid is populated
	 * once in the constructor (:367-375) and never mutated afterwards, so the
	 * flattened array is built lazily once and then reused.
	 *
	 * The array is shared, so treat it as read-only — callers that need to
	 * modify it must copy (`.slice()` / `.filter()`) first.
	 */
	get allhexes(): Hex[] {
		if (!this._allhexes) {
			this._allhexes = this.hexes.flat(1);
		}
		return this._allhexes;
	}

	/**
	 * Create attributes and populate JS grid with Hex objects
	 * @param {Partial<GridDefinition>} gridDefinition - specifies a number of columns in the grid.
	 * The resulting grid has jagged, symmetrical edges.
	 * Only "full" rows have the specified number of columns.
	 * @param {Game} game
	 * @example
	 * // {numRows:5, numCols:4, isFirstRowFull: true}
	 * //
	 * // x x x x - full row
	 * //  x x x  - partial row
	 * // x x x x - full row
	 * //  x x x  - partial row
	 * // x x x x - full row
	 * @constructor
	 */
	constructor(gridDefinition: Partial<GridDefinition>, game: Game) {
		const defaultGridDefinition = {
			numRows: 9,
			numCols: 16,
			isFirstRowFull: false,
		};

		gridDefinition = { ...defaultGridDefinition, ...gridDefinition };
		const numRows = gridDefinition.numRows;
		const numCols = gridDefinition.numCols;
		const isFirstRowFull = gridDefinition.isFirstRowFull;

		this.game = game;
		this.hexes = []; // Hex Array
		this.lastClickedHex = undefined;

		// The layer tree's shape and sibling order come from the shared
		// `LAYER_SPEC`, the same table the native container builder uses, so the two
		// cannot disagree. This fixes the smoke layer, which the previous inline
		// sequence appended after the creature layer and then tried to move with a
		// splice on a throwaway array.
		const layers = createBoardLayersWithFactory(game.gameEngine);
		this.display = layers.display;
		this.gridGroup = layers.gridGroup;
		this.trapGroup = layers.trapGroup;
		this.hexesGroup = layers.hexesGroup;
		this.displayHexesGroup = layers.displayHexesGroup;
		this.overlayHexesGroup = layers.overlayHexesGroup;
		this.dropGroup = layers.dropGroup;
		this.creatureGroup = layers.creatureGroup;
		// Behind the creatures so smoke never draws over a unit, but not a child of
		// any creature group, so it does not travel with one.
		this.infernalSmokeGroup = layers.infernalSmokeGroup;
		// Health indicators sit above all creature sprites so they're never occluded
		this.healthIndicatorUiGroup = layers.healthIndicatorUiGroup;
		// Parts of traps displayed over creatures
		this.trapOverGroup = layers.trapOverGroup;

		// Populate grid
		for (let row = 0; row < numRows; row++) {
			this.hexes.push([]);
			for (let hex = 0, len = numCols; hex < len; hex++) {
				if (hex == numCols - 1) {
					if ((row % 2 == 0 && !isFirstRowFull) || (row % 2 == 1 && isFirstRowFull)) {
						continue;
					}
				}

				this.hexes[row][hex] = new Hex(hex, row, this);
			}
		}

		this.selectedHex = this.hexes[0][0];

		// If true, clicking on a unit won't shout its name.
		this.onShoutCooldown = false;

		// If true, clicking a monster will instantly kill it.
		this._executionMode = this.game.metaPowersState.executeMonster;

		// Events
		this.game.channels.metaPowers.on('toggleExecuteMonster', (enabled: boolean) => {
			this._executionMode = enabled;
		});
		// When the dash opens or closes, creatures can remain in a "hovered" state
		// (e.g. bounce animation stuck). Reset all bounces to ensure a clean state.
		const resetBounces = () => {
			this.forEachHex((hex) => {
				const creature = hex.creature;
				if (creature instanceof Creature) {
					creature.resetBounce();
				}
			});
		};
		this.game.channels.ui.on('onOpenDash', resetBounces);
		this.game.channels.ui.on('onCloseDash', resetBounces);
	}

	get traps() {
		return this.game.traps;
	}

	hexAt(x: number, y: number): Hex | undefined {
		if (y < 0 || y >= this.hexes.length) return;
		const row = this.hexes[y];
		if (x < 0 || x >= row.length) return;
		return row[x];
	}

	isInBounds({ x, y }: Point) {
		return y < this.hexes.length && y >= 0 && x < this.hexes[y].length && x >= 0;
	}

	querySelf(o) {
		const game = this.game;
		const defaultOpt = {
			fnOnConfirm: () => {
				// No-op function.
			},
			fnOnSelect: (creature: Creature) => {
				creature.hexagons.forEach((hex) => {
					hex.overlayVisualState('creature selected player' + hex.creature.team);
				});
			},
			fnOnCancel: () => {
				this.game.activeCreature?.queryMove();
			},
			args: {},
			confirmText: 'Confirm',
			id: game.activeCreature.id,
		};

		o = { ...defaultOpt, ...o };

		game.activeCreature.hint(o.confirmText, 'confirm');

		this.queryHexes({
			fnOnConfirm: (hex, args) => {
				args.opt.fnOnConfirm(game.activeCreature, args.opt.args, { queryOptions: o });
			},
			fnOnSelect: (hex, args) => {
				args.opt.fnOnSelect(game.activeCreature, args.opt.args);
			},
			fnOnCancel: (hex, args) => {
				args.opt.fnOnCancel(game.activeCreature, args.opt.args);
			},
			args: {
				opt: o,
			},
			hexes: game.activeCreature.hexagons,
			hideNonTarget: true,
			id: o.id,
		});
	}

	/**
	 * Shortcut to queryChoice with specific directions.
	 * @param {QueryOptions} o
	 */
	queryDirection(o: Partial<QueryOptions>) {
		o.isDirectionsQuery = true;
		const defaultOpt = {
			team: Team.Enemy,
			id: 0,
			flipped: false,
			x: 0,
			y: 0,
			directions: [1, 1, 1, 1, 1, 1],
			includeCreature: true,
			stopOnCreature: true,
			pierceNumber: 1,
			pierceThroughBehavior: 'stop',
			distance: 0,
			minDistance: 0,
			distanceFalloff: 0,
			dashedHexesAfterCreatureStop: true,
			dashedHexesDistance: 0,
			dashedHexesUnderCreature: true,
			sourceCreature: undefined,
			isDirectionsQuery: true,
		};

		o = { ...defaultOpt, ...o };

		o = this.getDirectionChoices(o);
		this.queryChoice(o);

		return true;
	}

	/**
	 * Get an object that contains the choices and hexesDashed for a direction query.
	 * @param {QueryOptions} o Options.
	 * @returns {QueryOptions} Altered options.
	 */
	getDirectionChoices(o: Partial<QueryOptions>) {
		const defaultOpt = {
			team: Team.Enemy,
			requireCreature: true,
			id: 0,
			flipped: false,
			x: 0,
			y: 0,
			hexesDashed: [],
			shrunkenHexes: [],
			hexesDeadZone: [],
			directions: [1, 1, 1, 1, 1, 1],
			includeCreature: true,
			stopOnCreature: true,
			pierceNumber: 1,
			pierceThroughBehavior: 'stop',
			distance: 0,
			minDistance: 0,
			distanceFalloff: 0,
			dashedHexesAfterCreatureStop: true,
			dashedHexesDistance: 0,
			dashedHexesUnderCreature: true,
			sourceCreature: undefined,
			choices: [],
			optTest: () => true,
			ignoreCreatureTest: undefined,
			fillOnlyHoveredCreature: false,
		};

		const options = { ...defaultOpt, ...o };

		// Clean Direction
		this.forEachHex((hex) => {
			hex.direction = Direction.None;
		});

		options.choices = [];

		for (let i = 0, len = options.directions.length; i < len; i++) {
			if (!options.directions[i]) {
				continue;
			}

			const direction = i as Direction;
			let dir: Hex[] = [];
			let fx = 0;

			if (options.sourceCreature instanceof Creature) {
				const flipped = options.sourceCreature.player.flipped;
				if (
					(!flipped && direction > Direction.DownRight) ||
					(flipped && direction < Direction.DownLeft)
				) {
					fx = -1 * (options.sourceCreature.size - 1);
				}
			}

			dir = this.getHexLine(options.x + fx, options.y, direction, options.flipped);

			// Limit hexes based on distance
			if (options.distance > 0) {
				dir = dir.slice(0, options.distance + 1);
			}

			// The untargetable area between the unit and the minimum distance.
			let deadzone = [];
			if (options.minDistance > 0) {
				deadzone = dir.slice(0, options.minDistance);
				deadzone = arrayUtils.filterCreature(
					deadzone,
					options.includeCreature,
					options.stopOnCreature,
					options.id,
				);

				dir = dir.slice(
					// 1 greater than expected to exclude current (source creature) hex.
					options.minDistance,
				);
			}

			const hexesDeadZone = [];
			deadzone.forEach((element) => {
				hexesDeadZone.push(element);
			});

			/* If the ability has a minimum distance and units should block LOS, this
				direction cannot be used if there is a unit in the deadzone. */
			if (options.stopOnCreature && deadzone.length && this.atLeastOneTarget(deadzone, options)) {
				continue;
			}

			let hexesDashed = [];
			dir.forEach((item) => {
				item.direction = options.flipped ? 5 - direction : direction;

				if (options.stopOnCreature && options.dashedHexesAfterCreatureStop) {
					hexesDashed.push(item);
				}
			});

			arrayUtils.filterCreature(
				dir,
				options.includeCreature,
				options.stopOnCreature,
				options.id,
				options.sourceCreature,
				options.pierceNumber,
				options.pierceThroughBehavior as PierceThroughBehavior,
				options.team,
				options.ignoreCreatureTest,
			);

			if (dir.length === 0) {
				continue;
			}

			if (options.requireCreature && !this.atLeastOneTarget(dir, options)) {
				continue;
			}

			if (
				options.stopOnCreature &&
				options.includeCreature &&
				// Only straight direction.
				(direction === Direction.Right || direction === Direction.Left)
			) {
				if (arrayUtils.last(dir).creature instanceof Creature) {
					// Add all creature hexes.
					const creature = arrayUtils.last(dir).creature;
					dir.pop();
					// Sort along the direction the line actually travels on screen.
					// `dir` was built with `options.flipped` applied to `getHexLine`, so
					// the mirrored direction (5 - direction) must be used when the player
					// is flipped — otherwise the creature hexes get appended to the wrong
					// end of the line, putting the full-damage hexes at the far end and
					// the reduced-effect (shrunken) hexes near the caster.
					const sortDirection = options.flipped ? 5 - direction : direction;
					dir = arrayUtils.sortByDirection(dir.concat(creature.hexagons), sortDirection);
				}
			}

			dir.forEach((item) => {
				arrayUtils.removePos(hexesDashed, item);
			});

			/* For some reason hexesDashed can contain source creature hexagons. Rather
				than risk changing that logic, create a new list without the source creature. */
			const hexesDashedWithoutSourceCreature = arrayUtils.filterCreature(
				hexesDashed,
				true,
				false,
				options.id,
			);

			if (hexesDashed.length && options.dashedHexesDistance) {
				hexesDashed = hexesDashedWithoutSourceCreature.slice(0, options.dashedHexesDistance);
			}

			let shrunkenHexes: Hex[] = [];
			if (options.distanceFalloff) {
				/* Shrunken hexes do not replace existing hexes, instead they modify them.
					With that in mind, regular AND dashed hexes after the falloff distance
					can be shrunk. */
				shrunkenHexes = [...dir, ...hexesDashedWithoutSourceCreature].slice(
					options.distanceFalloff,
				);
			}

			// Deadzone hexes are also part of direction, so they should be clickable
			deadzone.forEach((element) => {
				dir.push(element);
			});

			options.hexesDashed = [...options.hexesDashed, ...hexesDashed];
			options.shrunkenHexes = [...options.shrunkenHexes, ...shrunkenHexes];
			options.hexesDeadZone = [...options.hexesDeadZone, ...hexesDeadZone];
			options.choices.push(dir);
		}

		return options;
	}

	/**
	 * Return whether there is at least one creature in the hexes that satisfies
	 * various conditions, e.g. team.
	 *
	 * @param {} dir ?
	 * @param {Object} o
	 * @return {boolean} At least one valid target.
	 */
	atLeastOneTarget(dir, o) {
		const defaultOpt = {
			team: Team.Both,
			optTest: function () {
				return true;
			},
		};

		const options = { ...defaultOpt, ...o };

		let validChoice = false;

		// Search each hex for a creature that matches the team argument.
		for (let j = 0; j < dir.length; j++) {
			const targetCreature = dir[j].creature;

			if (targetCreature instanceof Creature && targetCreature.id !== options.id) {
				const sourceCreature = this.game.creatures[options.id];

				if (
					isTeam(sourceCreature, targetCreature, options.team) &&
					options.optTest(targetCreature)
				) {
					validChoice = true;
					break;
				}
			}
		}

		if (validChoice) {
			return true;
		}

		return false;
	}

	/**
	 * fnOnSelect : 		Function : 	Function applied when clicking on one of the available hexes.
	 * fnOnConfirm : 		Function : 	Function applied when clicking again on the same hex.
	 * fnOnCancel : 		Function : 	Function applied when clicking a non reachable hex
	 * requireCreature : 	Boolean : 	Disable a choice if it does not contain a creature matching the team argument
	 * args : 				Object : 	Object given to the events function (to easily pass variable for these function)
	 */
	queryChoice(o) {
		const game = this.game;
		const defaultOpt = {
			fnOnConfirm: () => {
				game.activeCreature?.queryMove();
			},
			fnOnSelect: (choice) => {
				// When only filling the hovered creature
				if (o.fillOnlyHoveredCreature) {
					choice.forEach((item, index) => {
						if (item.creature instanceof Creature && item.creature === this.hoveredCreature) {
							item.displayVisualState('creature selected player' + item.creature.team);
						} else if (item.creature instanceof Creature) {
							item.displayVisualState('adj');
						} else {
							// Split the choice into two parts, before and after the empty hex
							const beforeEmpty = choice.slice(0, index);
							const afterEmpty = choice.slice(index + 1);
							// Check conditions
							if (beforeEmpty.some((hex) => hex.creature instanceof Creature)) {
								item.displayVisualState('dashed');
							} else if (afterEmpty.some((hex) => hex.creature instanceof Creature)) {
								item.displayVisualState('adj');
							}
						}
					});
				}
				// Normal behavior
				else {
					// Reset all choices to base state so only the hovered one is emphasised.
					o.choices.forEach((otherChoice) => {
						otherChoice.forEach((item) => {
							item.cleanDisplayVisualState('adj creature player0 player1 player2 player3');
						});
					});
					(o.hexesDeadZone || []).forEach((hex) => {
						hex.displayVisualState('deadzone');
					});
					choice.forEach((item) => {
						if (item.creature instanceof Creature) {
							item.displayVisualState('creature selected player' + item.creature.team);
						} else {
							item.displayVisualState('adj');
						}
					});
				}
			},
			fnOnCancel: () => {
				game.activeCreature?.queryMove();
			},
			fnOnHoverOutside: (() => {
				// Restore all choices to base/light state when pointer leaves the valid area.
				o.choices.forEach((choice) => {
					choice.forEach((item) => {
						item.cleanDisplayVisualState('adj creature player0 player1 player2 player3');
					});
				});
				(o.hexesDeadZone || []).forEach((hex) => {
					hex.displayVisualState('deadzone');
				});
			}) as (() => void) | undefined,
			team: Team.Enemy,
			requireCreature: 1,
			id: 0,
			args: {},
			flipped: false,
			choices: [],
			hexesDashed: [],
			hexesDeadZone: [],
			shrunkenHexes: [],
			isDirectionsQuery: false,
			hideNonTarget: true,
			dashedHexesUnderCreature: false,
			fillOnlyHoveredCreature: false,
		};

		// Overwrite any default options with options passed in through `o`
		o = { ...defaultOpt, ...o };

		let hexes = [];
		for (let i = 0, len = o.choices.length; i < len; i++) {
			let validChoice = true;

			if (o.requireCreature) {
				validChoice = false;
				// Search each hex for a creature that matches the team argument
				for (let j = 0; j < o.choices[i].length; j++) {
					if (o.choices[i][j].creature instanceof Creature && o.choices[i][j].creature != o.id) {
						const creaSource = game.creatures[o.id];
						const creaTarget = o.choices[i][j].creature;

						if (isTeam(creaSource, creaTarget, o.team)) {
							validChoice = true;
						}
					}
				}
			}

			if (validChoice) {
				hexes = hexes.concat(o.choices[i]);
				if (!(o as any).preserveDashedHexesInChoices) {
					o.choices[i].forEach((hex) => {
						arrayUtils.removePos(o.hexesDashed, hex);
					});
				}
			} else if (o.isDirectionsQuery) {
				this.forEachHex((hex) => {
					if (o.choices[i][0].direction == hex.direction) {
						arrayUtils.removePos(o.hexesDashed, hex);
					}
				});
			}
		}

		o.hexesDashed = o.dashedHexesUnderCreature
			? o.hexesDashed
			: o.hexesDashed.filter((hexDash) => !hexDash.creature);

		this.queryHexes({
			fnOnConfirm: (hex, args) => {
				// Determine which set of hexes (choice) the hex is part of
				for (let i = 0, len = args.opt.choices.length; i < len; i++) {
					for (let j = 0, lenj = args.opt.choices[i].length; j < lenj; j++) {
						if (hex.pos == args.opt.choices[i][j].pos) {
							args.opt.args.direction = hex.direction;
							args.opt.fnOnConfirm(args.opt.choices[i], args.opt.args, { queryOptions: o });
							return;
						}
					}
				}
			},
			fnOnSelect: (hex, args) => {
				// Determine which set of hexes (choice) the hex is part of
				for (let i = 0, len = args.opt.choices.length; i < len; i++) {
					for (let j = 0, lenj = args.opt.choices[i].length; j < lenj; j++) {
						if (hex.pos == args.opt.choices[i][j].pos) {
							args.opt.args.direction = hex.direction;
							args.opt.args.hex = hex;
							args.opt.args.choiceIndex = i;
							args.opt.fnOnSelect(args.opt.choices[i], args.opt.args, { queryOptions: o });
							return;
						}
					}
				}
			},
			fnOnCancel: o.fnOnCancel,
			fnOnHoverOutside: o.fnOnHoverOutside,
			args: {
				opt: o,
			},
			hexes: hexes,
			hexesDashed: o.hexesDashed,
			shrunkenHexes: o.shrunkenHexes,
			hexesDeadZone: o.hexesDeadZone,
			flipped: o.flipped,
			hideNonTarget: o.hideNonTarget,
			id: o.id,
			fillHexOnHover: false,
			fillOnlyHoveredCreature: o.fillOnlyHoveredCreature,
			targeting: o.targeting !== undefined ? o.targeting : true,
			callbackAfterQueryHexes: o.callbackAfterQueryHexes,
		});
	}

	/**
	 * @param {object} o Object given to the events function (to easily pass variable for these function)
	 * @param {function} o.fnOnSelect Function applied when clicking on one of the available hexes.
	 * @param {function} o.fnOnConfirm Function applied when clicking again on the same hex.
	 * @param {function} o.fnOnCancel Function applied when clicking a non reachable hex.
	 * @param {Team} o.team The targetable team.
	 * @param {number} o.id Creature ID
	 * @param {boolean} o.replaceEmptyHexesWithDashed Replace all non targetable, empty hexes with dashed hexes.
	 * 	o.hexesDashed will override this option.
	 */
	queryCreature(o) {
		const game = this.game;
		const defaultOpt = {
			fnOnConfirm: () => {
				game.activeCreature?.queryMove();
			},
			fnOnSelect: (creature) => {
				creature.tracePosition({
					overlayClass: 'creature selected player' + creature.team,
				});
			},
			fnOnCancel: () => {
				game.activeCreature?.queryMove();
			},
			optTest: () => true,
			args: {},
			hexes: [],
			hexesDashed: [],
			hexesDeadZone: [],
			flipped: false,
			id: 0,
			team: Team.Enemy,
			replaceEmptyHexesWithDashed: false,
		};

		o = { ...defaultOpt, ...o };

		/* Divide hexes into:
		- containing valid targets
		- empty (no possible target)
		Hexes containing invalid targets (wrong team, o.optTest, etc) are discard. */
		const { targetHexes, emptyHexes } = o.hexes.reduce(
			(acc, hex) => {
				const sourceCreature = game.creatures[o.id];
				const targetCreature = hex.creature;

				const acceptTargetHex = () => {
					return {
						...acc,
						targetHexes: [...acc.targetHexes, hex],
					};
				};

				const acceptEmptyHex = () => {
					return {
						...acc,
						emptyHexes: [...acc.emptyHexes, hex],
					};
				};

				const discardHex = () => {
					return acc;
				};

				if (!targetCreature) {
					return acceptEmptyHex();
				}

				if (targetCreature instanceof Creature && targetCreature.id !== o.id) {
					if (!o.optTest(hex.creature)) {
						return discardHex();
					}

					if (isTeam(sourceCreature, targetCreature, o.team)) {
						return acceptTargetHex();
					}
				}

				return discardHex();
			},
			{ targetHexes: [], emptyHexes: [] },
		);

		o.hexes = targetHexes;

		if (o.replaceEmptyHexesWithDashed && !o.hexesDashed.length) {
			o.hexesDashed = emptyHexes;
		}

		let extended = [];
		/* Add creature hexes that extend out of the range of the source hexes, so the
		entire creature can be highlighted. */
		o.hexes.forEach((hex) => {
			extended = extended.concat(hex.creature.hexagons);
		});

		o.hexes = extended;

		// Xray: make obstructors of all valid ability targets semi-transparent so
		// the player can see every targetable unit clearly before hovering.
		const abilityActiveCreature = this.game.activeCreature;
		const seenTargets = new Set<Creature>();
		o.hexes.forEach((hex) => {
			const c = hex.creature;
			if (c instanceof Creature && c !== abilityActiveCreature && !seenTargets.has(c)) {
				seenTargets.add(c);
				c.hexagons.forEach((h) => h.ghostOverlap(c));
				c.xray(false); // target itself must remain fully opaque
			}
		});

		// Active creature (attacker) must never be xrayed — ghostOverlap for a
		// target's hexes can pick it up as a same-row or adjacent-row candidate.
		if (abilityActiveCreature instanceof Creature) {
			abilityActiveCreature.xray(false);
		}

		this.queryHexes({
			fnOnConfirm: (hex, args) => {
				const { creature } = hex;
				if (!creature) return;
				args.opt.fnOnConfirm(creature, args.opt.args, { queryOptions: o });
			},
			fnOnSelect: (hex, args) => {
				const { creature } = hex;
				if (!creature) return;
				args.opt.fnOnSelect(creature, args.opt.args);
			},
			fnOnCancel: o.fnOnCancel,
			args: {
				opt: o,
			},
			hexes: o.hexes,
			hexesDashed: o.hexesDashed,
			hexesDeadZone: o.hexesDeadZone,
			flipped: o.flipped,
			hideNonTarget: true,
			id: o.id,
		});
	}

	redoLastQuery() {
		// A replayed query is anchored to the creature that issued it. With no
		// active creature the match has ended or reset, so re-running it would
		// overlay a dead unit's reachable hexes and dereference a null
		// `activeCreature` on the way through.
		if (!this.lastQueryOpt || !this.game.activeCreature) {
			return;
		}
		this.queryHexes(this.lastQueryOpt);
	}

	/**
	 * Re-evaluate hover state for the hex currently under the pointer.
	 * Call this whenever freezedInput transitions to false so the cursor and
	 * visual highlights update without requiring mouse movement.
	 */
	refreshHoverState() {
		if (this.suppressNextHoverRefresh) {
			this.suppressNextHoverRefresh = false;
			return;
		}
		if (this.game.botController?.isBotTurn()) {
			return;
		}
		// Nothing to replay when the pointer has left the board: the last hex it
		// crossed is not where it is, and re-firing hover there would light up a
		// unit the player is no longer pointing at.
		if (!isPointerWithinBoard()) return;
		const hex = this.lastMouseHex;
		if (!hex || this.game.freezedInput || this.isRefreshingHoverState) return;
		this.cancelDeferredActiveHexDashedClear();
		// Replicate what the pointer-over handler does so cursor, unit preview and
		// xray all update.
		if (hex.reachable && this.game.activeCreature) {
			this.game.activeCreature.highlightCurrentHexesAsDashed();
		}
		this.game.channels.hex.emit('over', { hex });
		this.selectedHex = hex;
		this.isRefreshingHoverState = true;
		try {
			hex.onSelectFn(hex);
		} finally {
			this.isRefreshingHoverState = false;
		}
	}

	cancelDeferredActiveHexDashedClear() {
		if (this.activeHexDashedClearTimeout) {
			clearTimeout(this.activeHexDashedClearTimeout);
			this.activeHexDashedClearTimeout = null;
		}
	}

	scheduleDeferredActiveHexDashedClear() {
		this.cancelDeferredActiveHexDashedClear();
		this.activeHexDashedClearTimeout = setTimeout(() => {
			this.activeHexDashedClearTimeout = null;
			this.game.activeCreature?.clearDashedOverlayOnHexes();
		}, 0);
	}

	/**
	 * fnOnSelect : 	Function : 	Function applied when clicking on one of the available hexes.
	 * fnOnConfirm : 	Function : 	Function applied when clicking again on the same hex.
	 * fnOnCancel : 	Function : 	Function applied when clicking a non reachable hex
	 * args : 			Object : 	Object given to the events function (to easily pass variable for these function)
	 * hexes : 		Array : 	Reachable hexes
	 * callbackAfterQueryHexes : 		Function : 	empty function to be overridden with custom logic to execute after queryHexes
	 */
	queryHexes(o) {
		const game = this.game;
		const getCreatureDisplayName = (creature: Creature) => {
			const withoutPrefix = creature.name.replace(/^object[_-]/i, '');
			const spacedName = withoutPrefix.replace(/[_-]+/g, ' ').trim();
			if (!spacedName) {
				return creature.name;
			}

			return spacedName.charAt(0).toUpperCase() + spacedName.slice(1);
		};
		// Detect whether this is a fresh query or a redo of the last query.
		// redoLastQuery() passes the same lastQueryOpt reference, so reference
		// equality distinguishes the two cases.
		const isFreshQuery = o !== this.lastQueryOpt;
		if (isFreshQuery) {
			this.queryGeneration++;
		}
		const defaultOpt = {
			fnOnConfirm: () => {
				game.activeCreature?.queryMove();
			},
			fnOnSelect: (hex: Hex) => {
				game.activeCreature.faceHex(hex);
				hex.overlayVisualState('creature selected player' + game.activeCreature.team);
			},
			fnOnCancel: () => {
				game.activeCreature?.queryMove();
			},
			fnOnHoverOutside: undefined as (() => void) | undefined,
			fnOnHover: undefined as ((hex: Hex) => void) | undefined,
			callbackAfterQueryHexes: () => {
				// empty function to be overridden with custom logic to execute after queryHexes
			},
			args: {},
			hexes: [],
			hexesDashed: [],
			shrunkenHexes: [],
			hexesDeadZone: [],
			size: 0,
			id: 0,
			flipped: false,
			hideNonTarget: false,
			ownCreatureHexShade: false,
			targeting: true,
			fillHexOnHover: true,
			fillOnlyHoveredCreature: false,
		};

		o = { ...defaultOpt, ...o };

		this.lastClickedHex = undefined;

		// Save the last Query
		this.lastQueryOpt = { ...o };

		const clearPreviewOverlay = (preview) => {
			if (!preview) {
				return;
			}

			clearPreviewTweens(game, preview);
			preview.alpha = 0;

			if (preview._previewPos === undefined) {
				return;
			}

			for (let i = 0; i < preview._previewSize; i++) {
				const prevHex = this.hexes[preview._previewPos.y]?.[preview._previewPos.x - i];
				if (!prevHex || prevHex.creature === game.activeCreature) {
					continue;
				}

				this.cleanHex(prevHex);
				this.restoreReachableHexVisual(prevHex);
			}

			preview._previewPos = undefined;
		};

		// Reset keyboard cursor to the active creature's front hexagon so that
		// arrow-key navigation always starts from a consistent, tactically useful
		// position rather than wherever the cursor happened to be last.
		// Only do this for fresh queries; redoLastQuery() must not move the cursor
		// mid-flight (it is called from clearHexViewAlterations inside selectHex*).
		if (isFreshQuery) {
			const activeCreature = game.activeCreature;
			if (activeCreature?.hexagons?.length) {
				const frontHex = activeCreature.player.flipped
					? activeCreature.hexagons[activeCreature.size - 1]
					: activeCreature.hexagons[0];
				if (frontHex) {
					this.selectedHex = frontHex;
				}
			}
		}

		this.updateDisplay();
		// Block all hexes
		this.forEachHex((hex) => {
			hex.unsetReachable();

			if (o.hideNonTarget) {
				hex.setNotTarget();
			} else {
				hex.unsetNotTarget();
			}

			if (o.hexesDashed.indexOf(hex) !== -1) {
				hex.displayVisualState('dashed');
			} else {
				hex.cleanDisplayVisualState('dashed');
			}

			if (o.hexesDeadZone.indexOf(hex) !== -1) {
				hex.displayVisualState('deadzone');
			} else {
				hex.cleanDisplayVisualState('deadzone');
			}

			if (o.shrunkenHexes.includes(hex)) {
				hex.displayVisualState('shrunken');
			} else {
				hex.cleanDisplayVisualState('shrunken');
			}
		});

		// Cleanup
		clearPreviewOverlay(this.materialize_overlay);
		clearPreviewOverlay(this.secondary_overlay);

		if (!o.ownCreatureHexShade) {
			if (o.id instanceof Array) {
				o.id.forEach((id) => {
					game.creatures[id].hexagons.forEach((hex) => {
						hex.overlayVisualState('ownCreatureHexShade');
					});
				});
			} else {
				if (o.id != 0) {
					game.creatures[o.id].hexagons.forEach((hex) => {
						hex.overlayVisualState('ownCreatureHexShade');
					});
				}
			}
		}

		// Function to find the path of a given hex
		const findDirectionalPathOfHex = (hex) => {
			let startIndex = o.hexes.indexOf(hex);
			let endIndex = startIndex;
			// Find the start of the path
			while (startIndex > 0 && o.hexes[startIndex - 1].direction === hex.direction) {
				startIndex--;
			}
			// Find the end of the path
			while (endIndex < o.hexes.length - 1 && o.hexes[endIndex + 1].direction === hex.direction) {
				endIndex++;
			}
			// Extract the path
			return o.hexes.slice(startIndex, endIndex + 1);
		};

		// Function to determine if an empty hex is before or after the first creature in path
		const emptyHexBeforeCreature = (hex) => {
			const path = findDirectionalPathOfHex(hex);
			const index = path.findIndex((h) => h === hex);
			const beforeEmpty = path.slice(0, index);
			const afterEmpty = path.slice(index + 1);
			// Check conditions
			if (beforeEmpty.some((hex) => hex.creature instanceof Creature)) {
				return false;
			} else if (afterEmpty.some((hex) => hex.creature instanceof Creature)) {
				return true;
			}
		};
		// Set reachable the given hexes
		o.hexes.forEach((hex) => {
			hex.setReachable();
			if (o.hideNonTarget) {
				hex.unsetNotTarget();
			}
			if (o.targeting) {
				if (hex.creature instanceof Creature) {
					if (hex.creature.id != this.game.activeCreature?.id) {
						hex.overlayVisualState('reachable h_player' + hex.creature.team);
						// Add dashed hexagons under targets for ranged abilities with team color
						hex.displayVisualState('dashed player' + hex.creature.team);
						// Ensure dashed hexagons are on top for better visibility
						hex.grid.displayHexesGroup.bringToTop(hex.display);
					}
				} else {
					if (o.fillOnlyHoveredCreature && !emptyHexBeforeCreature(hex)) {
						hex.displayVisualState('dashed');
					} else if (this.game.activeCreature) {
						hex.overlayVisualState('reachable h_player' + this.game.activeCreature.team);
					}
				}
			}
		});

		if (o.callbackAfterQueryHexes) {
			o.callbackAfterQueryHexes();
		}

		const onCreatureHover = (creature: Creature, queueEffect, hex: Hex) => {
			this.hoveredCreature = creature;
			if (creature.isDarkPriest()) {
				if (creature === game.activeCreature) {
					if (creature.hasCreaturePlayerGotPlasma()) {
						creature.displayPlasmaShield();
					}
				} else {
					creature.displayHealthStats();
				}
			}
			creature.hexagons.forEach((h) => {
				// Flashing outline
				h.overlayVisualState('hover h_player' + creature.team);
				// Keep the dashed hexagons visible under targets with team color
				if (h.displayClasses.indexOf('dashed') === -1) {
					h.displayVisualState('dashed player' + creature.team);
				}
				// Make sure the display hexagon is brought to the top for better visibility
				h.grid.displayHexesGroup.bringToTop(h.display);
			});
			if (creature !== game.activeCreature) {
				if (!hex.reachable) {
					$j('canvas').css('cursor', this.getCursorForMultiplayer('n-resize'));
				} else {
					// Filled hex with color
					hex.displayVisualState('creature player' + hex.creature.team);
				}
			} else if (game.activeCreature.noActionPossible) {
				$j('canvas').css('cursor', this.getCursorForMultiplayer('progress'));
			}
			queueEffect(creature.id);
		};

		// Once a reachable hex is confirmed, ignore any late hover callbacks tied to
		// this query instance until queryHexes() installs a fresh set of handlers.
		let isQueryLockedAfterConfirm = false;

		// ONCLICK
		const onConfirmFn = (hex: Hex) => {
			if (isQueryLockedAfterConfirm) {
				return;
			}

			// Debugger
			const y = hex.y;
			let x = hex.x;

			// Clear display and overlay
			$j('canvas').css('cursor', this.getCursorForMultiplayer('pointer'));

			if (this._executionMode && hex.creature instanceof Creature) {
				hex.creature.die({ player: game.players[0] });
				return;
			}

			// Not reachable hex
			if (!hex.reachable) {
				this.lastClickedHex = undefined;

				if (hex.creature instanceof Creature) {
					// If creature
					onCreatureHover(
						hex.creature,
						game.activeCreature !== hex.creature
							? game.UI.bouncexrayQueue.bind(game.UI)
							: game.UI.xrayQueue.bind(game.UI),
						hex,
					);

					// Shout unit's name, show tooltip with unit's name and start a cooldown.
					if (!this.onShoutCooldown) {
						this.onShoutCooldown = true;
						const shoutName = hex.creature.name;
						const displayName = getCreatureDisplayName(hex.creature);
						game.soundsys.playShout(shoutName);
						hex.creature.hint(displayName, 'creature_name');

						setTimeout(() => {
							this.onShoutCooldown = false;
						}, 1200);
					}
				} else {
					// If nothing
					if (game.activeCreature.noActionPossible) {
						game.skipTurn();
					} else {
						o.fnOnCancel(hex, o.args); // ON CANCEL
					}
				}
			} else {
				// Reachable hex
				// Offset Pos
				const offset = o.flipped ? o.size - 1 : 0;
				const mult = o.flipped ? 1 : -1; // For flipped player

				// If only filling hovered creatures hexes, cancel if player clicks on empty hex after first creature
				if (o.fillOnlyHoveredCreature && !emptyHexBeforeCreature(hex)) {
					if (!(hex.creature instanceof Creature)) {
						o.fnOnCancel(hex, o.args); // ON CANCEL
						return;
					}
				}

				// If hex is reachable & creature, reset target bounce.
				// Preserve active creature bounce (bot can confirm without a hover-off cycle).
				if (hex.creature instanceof Creature && hex.creature !== game.activeCreature) {
					hex.creature.resetBounce();
				}

				for (let i = 0, size = o.size; i < size; i++) {
					// Try next hexagons to see if they fits
					if (x + offset - i * mult >= this.hexes[y].length || x + offset - i * mult < 0) {
						continue;
					}

					if (this.hexes[y][x + offset - i * mult].isWalkable(o.size, o.id)) {
						x += offset - i * mult;
						break;
					}
				}

				hex = this.hexes[y][x]; // New coords
				game.activeCreature.faceHex(hex);
				isQueryLockedAfterConfirm = true;
				this.lastMouseHex = undefined;

				if (game.activeCreature === hex.creature && hex.creature.noActionPossible) {
					game.UI.hoveringNoActionCreature = false;
					// Clear noActionPossible before fading so any cleanup queryMove(null)
					// during turn-end deactivation does not re-trigger querySelf and spawn
					// a second Skip turn marker on top of the fading one.
					hex.creature.noActionPossible = false;
					hex.creature.fadeOutNoActionHints();
				}

				if (hex !== this.lastClickedHex) {
					this.lastClickedHex = hex;
				}

				// Keep primary materialize preview alive for summon handoff:
				// Creature.summon() uses fadeOutTempCreature() for a smooth transition.
				clearPreviewOverlay(this.secondary_overlay);

				o.fnOnConfirm(hex, o.args, { queryOptions: o });
			}
		};

		const onHoverOffFn = (hex: Hex) => {
			if (isQueryLockedAfterConfirm) {
				return;
			}

			const { creature } = hex;

			if (creature instanceof Creature) {
				this.hoveredCreature = null;
				creature.resetBounce();
				if (creature === game.activeCreature) {
					creature.startBounce();
				}
				// toggle hover off event
				if (creature.isDarkPriest()) {
					// the plasma would have been displayed so now display the health again
					creature.updateHealth();
				}

				if (game.activeCreature === hex.creature && hex.creature.noActionPossible) {
					game.UI.hoveringNoActionCreature = false;
					game.UI.btnSkipTurn.$button.removeClass('hidden');
					// Stop bouncing no-action hint when cursor leaves, but keep it visible.
					creature.stopNoActionHintBounce();
				}
			}
			if (window.innerWidth > 600 || window.innerHeight > 700) {
				game.UI.chat.hideExpanded();
			}
			$j('canvas').css('cursor', this.getCursorForMultiplayer('default'));
		};

		// ONMOUSEOVER
		const onSelectFn = (hex: Hex) => {
			if (isQueryLockedAfterConfirm) {
				return;
			}

			// The active creature can be cleared by endGame() (e.g. when the Dark
			// Priest dies mid-animation) while a stale hover query is still firing
			// its mouse-move handler — there is no board left to render a hover for.
			if (!game.activeCreature) {
				return;
			}

			let { x } = hex;
			const { y } = hex;
			const hoveredHex = hex;
			const queryGeneration = this.queryGeneration;

			// Xray
			this.xray(hex);

			// Clear display and overlay
			game.UI.xrayQueue(-1);
			$j('canvas').css('cursor', this.getCursorForMultiplayer('pointer'));
			$j('body').css('cursor', 'default');

			if (hex.creature instanceof Creature) {
				if (!game.botController?.isBotTurn()) {
					game.UI.chat.showExpanded(hex.creature);
				}
				// Keep reference
				onCreatureHover(hex.creature, game.UI.xrayQueue.bind(game.UI), hex);

				hex.creature.startBounce();

				if (game.activeCreature === hex.creature && hex.creature.noActionPossible) {
					game.UI.hoveringNoActionCreature = true;
					game.UI.btnSkipTurn.$button.removeClass('bounce');
					game.UI.btnSkipTurn.$button.removeClass('hidden');
					// Show "Skip Turn" icon
					hex.creature.hint('Skip turn', 'no_action');
				}
				game.UI.chat.isOverCreature = true;
			}

			if (hex.reachable) {
				if (o.fillOnlyHoveredCreature && !(hex.creature instanceof Creature)) {
					if (!emptyHexBeforeCreature(hex)) {
						$j('canvas').css('cursor', this.getCursorForMultiplayer('not-allowed'));
						hex.overlayVisualState('hover');
					} else {
						const index = o.hexes.indexOf(hex);
						const afterEmpty = o.hexes.slice(index + 1);
						// Find the next creature after the empty hex
						const nextCreature = afterEmpty.find(
							(hex) => hex.creature instanceof Creature,
						)?.creature;
						if (nextCreature) {
							// Apply the desired behavior to all hexes the next creature occupies
							nextCreature.hexagons.forEach((creatureHex) => {
								creatureHex.displayVisualState('creature selected player' + nextCreature.team);
							});
						}
					}
				}

				if (o.fillHexOnHover) {
					this.cleanHex(hex);
					hex.displayVisualState('creature player' + this.game.activeCreature.team);
				}

				// Allow custom hover handling (e.g. target.png marking during ability targeting).
				if (o.fnOnHover) {
					o.fnOnHover(hex);
				}

				// Offset Pos
				const offset = o.flipped ? o.size - 1 : 0;
				const mult = o.flipped ? 1 : -1; // For flipped player

				for (let i = 0, size = o.size; i < size; i++) {
					// Try next hexagons to see if they fit
					if (x + offset - i * mult >= this.hexes[y].length || x + offset - i * mult < 0) {
						continue;
					}
					if (this.hexes[y][x + offset - i * mult].isWalkable(o.size, o.id)) {
						x += offset - i * mult;
						break;
					}
				}

				hex = this.hexes[y][x]; // New coords
				o.fnOnSelect(hex, o.args);
				// Choice callbacks can clear overlays while filling an entire area.
				// Mark the actual input hex afterwards, not the size-adjusted anchor.
				if (
					this.queryGeneration === queryGeneration &&
					!this.materialize_overlay?._previewPos &&
					!this.secondary_overlay?._previewPos
				) {
					hoveredHex.overlayVisualState('hover');
				}
			} else if (!hex.reachable) {
				// Reset the query so the movement path traced on the previous reachable
				// hex (tracePath's `adj` hexes) is cleaned instead of lingering as dark
				// hexagons once the cursor leaves range. Mirrors what selectNormal does
				// via redoLastQuery() before tracing a new path.
				this.redoLastQuery();
				// Clean the last preview position's hex overlays and reset tracking so
				// that re-entering the spawn range doesn't leave a ghost outline behind.
				clearPreviewOverlay(this.materialize_overlay);
				clearPreviewOverlay(this.secondary_overlay);
				hex.overlayVisualState('hover');

				$j('canvas').css(
					'cursor',
					game.activeCreature.noActionPossible ? 'progress' : 'not-allowed',
				);

				if (o.fnOnHoverOutside) {
					o.fnOnHoverOutside();
				}

				// If creature and inactive
				if (hex.creature instanceof Creature && hex.creature !== game.activeCreature) {
					$j('canvas').css('cursor', this.getCursorForMultiplayer('s-resize'));
				}
			}
		};

		// ONRIGHTCLICK
		const onRightClickFn = (hex: Hex) => {
			if (isQueryLockedAfterConfirm) {
				return;
			}

			if (hex.creature instanceof Creature) {
				if (hex.creature.name.startsWith('object_')) {
					game.UI.showCreature(game.activeCreature.type, game.activeCreature.player.id, 'emptyHex');
				} else {
					game.UI.showCreature(hex.creature.type, hex.creature.player.id, 'grid');
				}
			} else {
				if (game.activeCreature.isDarkPriest()) {
					if (game.UI.selectedCreatureObj) {
						game.UI.toggleDash(false);
					} else {
						game.UI.showCreature(
							game.activeCreature.type,
							game.activeCreature.player.id,
							'emptyHex',
						);
					}
				} else {
					game.UI.showCreature(game.activeCreature.type, game.activeCreature.player.id, 'emptyHex');
				}
			}
		};

		this.forEachHex((hex) => {
			hex.onSelectFn = onSelectFn;
			hex.onHoverOffFn = onHoverOffFn;
			hex.onConfirmFn = onConfirmFn;
			hex.onRightClickFn = onRightClickFn;
		});

		// All hex handlers are now up to date; refresh only for fresh queries.
		// redoLastQuery() is called from hover preview flows and must not retrigger
		// onSelectFn here, or it can recurse into queryHexes and freeze the game.
		if (isFreshQuery) {
			this.refreshHoverState();
		}

		if (this.game.botController?.shouldAutoResolveQuery()) {
			this.game.botController.resolveQuery(o, {
				onSelect: onSelectFn,
				onConfirm: onConfirmFn,
			});
		}
	}

	/**
	 * @param {Hex} hex - Hexagon to emphasize.
	 *
	 * If hex contain creature call ghostOverlap for each creature hexes
	 */
	xray(hex: Hex) {
		if (this.game.animations?.xraySuppressed) {
			return;
		}
		this.lastXrayHex = hex;
		this.game.creatures.forEach((creature) => {
			if (creature instanceof Creature) {
				creature.xray(false);
			}
		});

		const { activeCreature } = this.game;
		if (!(activeCreature instanceof Creature)) {
			return;
		}

		const noAbilitySelected = this.game.UI?.selectedAbility === -1;
		const hoveredCreature =
			hex.creature instanceof Creature ? (hex.creature as Creature) : undefined;
		const hoveredTrapSprites = this.game.traps
			.filter((trap) => trap.x === hex.x && trap.y === hex.y)
			.flatMap((trap) => trap.getVisualSprites())
			.filter((sprite) => sprite.active && typeof sprite.getBounds === 'function');
		const hoveredTrap =
			hoveredTrapSprites.length > 0 ||
			this.game.traps.some((trap) => trap.x === hex.x && trap.y === hex.y);
		const hoveredDropSprites = (this.game.drops ?? [])
			.filter((drop) => drop.x === hex.x && drop.y === hex.y && !drop.pickedUp)
			.map((drop) => drop.display)
			.filter((sprite) => sprite.active && typeof sprite.getBounds === 'function');
		const hoveredDrop = hoveredDropSprites.length > 0 || Boolean(hex.drop);
		const hoveredRevealSprites = [...hoveredTrapSprites, ...hoveredDropSprites];
		const hoveredRevealCreature = hoveredCreature instanceof Creature ? hoveredCreature : undefined;
		const hoveredNonActiveCreature =
			hoveredCreature && hoveredCreature !== activeCreature ? hoveredCreature : undefined;

		// Exception 1/2: reveal hovered non-active target when no ability is selected.
		// Skip when a trap/drop is also on the hex — Exception 3 handles that case
		// and must also xray the creature standing on the trap.
		if (hoveredNonActiveCreature && noAbilitySelected && !hoveredTrap && !hoveredDrop) {
			hoveredNonActiveCreature.hexagons.forEach((hoveredHex) =>
				hoveredHex.ghostOverlap(hoveredNonActiveCreature),
			);
			hoveredNonActiveCreature.xray(false);
			return;
		}

		// Exception 3: reveal hovered traps and drops regardless of movement reachability.
		if (hoveredTrap || hoveredDrop) {
			if (hoveredRevealCreature) {
				hoveredRevealCreature.hexagons.forEach((hoveredHex) =>
					hoveredHex.ghostOverlap(hoveredRevealCreature),
				);
				hoveredRevealCreature.xray(false);
			}

			if (hoveredRevealSprites.length === 0) {
				hex.ghostOverlap();
				return;
			}

			const revealReferences = hoveredRevealSprites.map((sprite) => {
				return {
					sprite,
					grp: this.creatureGroup,
				} as unknown as Creature;
			});
			if (hoveredRevealCreature) {
				revealReferences.push(hoveredRevealCreature);
			}

			this.game.creatures.forEach((candidate) => {
				if (!(candidate instanceof Creature)) {
					return;
				}
				if (candidate === hoveredRevealCreature || candidate === activeCreature) {
					return;
				}
				if (!candidate.sprite || typeof candidate.sprite.getBounds !== 'function') {
					return;
				}

				// Always xray a creature sitting directly on the hovered trap/drop hex
				// (its sprite bounds may not intersect the trap sprite, e.g. tall Abolished
				// standing on a small bonfire flame).
				const isOnTrapHex =
					candidate !== activeCreature &&
					candidate.hexagons.some((h) => h.x === hex.x && h.y === hex.y);

				if (!isOnTrapHex) {
					const candidateBounds = safeSpriteBounds(candidate.sprite);
					// Unmeasurable sprite: treat as non-overlapping rather than
					// xraying on a guess.
					if (!candidateBounds) return;
					const overlapsReveal = hoveredRevealSprites.some((sprite) => {
						const revealBounds = safeSpriteBounds(sprite);
						if (!revealBounds) return false;
						return !(
							candidateBounds.right <= revealBounds.left ||
							candidateBounds.left >= revealBounds.right ||
							candidateBounds.bottom <= revealBounds.top ||
							candidateBounds.top >= revealBounds.bottom
						);
					});
					if (!overlapsReveal) {
						return;
					}
				}

				candidate.xray(
					true,
					revealReferences.length === 1 ? revealReferences[0] : revealReferences,
				);
			});
			return;
		}

		// Default: keep active creature visible through obstructions.
		activeCreature.hexagons.forEach((activeHex) => activeHex.ghostOverlap(activeCreature));
		activeCreature.xray(false);
	}

	/**
	 * Gets a line of hexes given a start point and a direction The result is an array
	 * of hexes, starting from the start point's hex, and extending out in a straight line.
	 * If the coordinate is erroneous, returns an empty array.
	 *
	 * @param {number} x - Coordinate of start hex.
	 * @param {number} y - Coordinate of start hex.
	 * @param {Direction} dir - Direction of the line.
	 * @param {boolean} flipped - Flip the direction.
	 * @returns {Hex[]} Hexes in the line.
	 */
	getHexLine(x: number, y: number, dir: Direction, flipped: boolean): Hex[] {
		switch (dir) {
			case Direction.UpRight:
				return this.getHexMap(x, y - 8, 0, flipped, matrices.diagonalup).reverse();
			case Direction.Right:
				return this.getHexMap(x, y, 0, flipped, matrices.straitrow);
			case Direction.DownRight:
				return this.getHexMap(x, y, 0, flipped, matrices.diagonaldown);
			case Direction.DownLeft:
				return this.getHexMap(x, y, -4, flipped, matrices.diagonalup);
			case Direction.Left:
				return this.getHexMap(x, y, 0, !flipped, matrices.straitrow);
			case Direction.UpLeft:
				return this.getHexMap(x, y - 8, -4, flipped, matrices.diagonaldown).reverse();
			default:
				return [];
		}
	}

	cleanHex(hex: Hex) {
		const activeCreature = this.game.activeCreature;
		const isActiveCreatureHex =
			activeCreature && hex.creature instanceof Creature && hex.creature.id === activeCreature.id;
		const preserveDeadzone =
			Array.isArray(this.lastQueryOpt?.hexesDeadZone) &&
			this.lastQueryOpt.hexesDeadZone.indexOf(hex) !== -1;

		if (isActiveCreatureHex) {
			// Preserve the active creature's persistent display/overlay classes so any
			// hover preview or path cleanup cannot restart the glow state.
			hex.cleanDisplayVisualState('adj hover dashed shrunken deadzone hidden');
			hex.cleanOverlayVisualState(
				'reachable weakDmg moveto selected hover ownCreatureHexShade h_player0 h_player1 h_player2 h_player3 p0 p1 p2 p3',
			);
			if (preserveDeadzone) {
				hex.displayVisualState('deadzone');
			}
			return;
		}

		// A confirmed Crashing Globe target keeps its `target.png` marking until
		// the projectile lands, but the cursor is transient and must be removed.
		if (hex._markedByCrashingGlobe) {
			hex.cleanDisplayVisualState();
			hex.cleanOverlayVisualState();
			if (preserveDeadzone) {
				hex.displayVisualState('deadzone');
			}
			return;
		}

		hex.cleanDisplayVisualState();
		hex.cleanOverlayVisualState();
		if (preserveDeadzone) {
			hex.displayVisualState('deadzone');
		}
	}

	restoreReachableHexVisual(hex: Hex) {
		if (!hex.reachable || !this.game.activeCreature) {
			return;
		}

		if (this.lastQueryOpt?.targeting) {
			hex.overlayVisualState('reachable h_player' + this.game.activeCreature.team);
		}
	}

	/**
	 * Clear transient hover visuals for a single hex without rebuilding the whole
	 * query state. This is used during mouse transitions between adjacent hexes.
	 */
	clearTransientHexHoverVisual(hex: Hex) {
		if (!this.lastQueryOpt) {
			return;
		}

		const activeCreature = this.game.activeCreature;
		const isActiveCreatureHex =
			activeCreature && hex.creature instanceof Creature && hex.creature.id === activeCreature.id;
		const preserveDeadzone =
			Array.isArray(this.lastQueryOpt?.hexesDeadZone) &&
			this.lastQueryOpt.hexesDeadZone.indexOf(hex) !== -1;

		if (isActiveCreatureHex) {
			// Clean only transient display state so the creature's persistent `creature`
			// and `playerN` classes stay intact. That avoids reintroducing outline hexes
			// while still removing hover-added dashed/path state.
			hex.cleanDisplayVisualState('adj hover dashed shrunken deadzone hidden');
			hex.cleanOverlayVisualState(
				'hover h_player0 h_player1 h_player2 h_player3 p0 p1 p2 p3 crashing-globe-target',
			);
			if (preserveDeadzone) {
				hex.displayVisualState('deadzone');
			}
			return;
		}

		this.cleanHex(hex);
		this.restoreReachableHexVisual(hex);

		// Restore the base query display class after transient hover cleanup so
		// sideways cursor movement does not leave a lighter/transparent-looking hex.
		const queryOpt = this.lastQueryOpt as any;

		// `cleanHex` above strips every display class, including `shrunken`, and
		// the branches below only restore `dashed`/`adj`. A shrunken hex that was
		// hovered therefore comes off hover at full size — its display sprite
		// keeps the 0.5 scale set by `updateStyle()` only while the `shrunken`
		// class is present, so re-adding it here puts the hex back at reduced,
		// centered scale. This must run before the creature early-return below:
		// a target unit's hexes at the end of a long path are shrunken too, and
		// skipping them here would leave those last hexagons at full size.
		if (Array.isArray(queryOpt.shrunkenHexes) && queryOpt.shrunkenHexes.indexOf(hex) !== -1) {
			hex.displayVisualState('shrunken');
		}

		// A dashed hex is part of the query's own footprint, so it outlives the
		// hover cursor whether or not a unit stands on it. This has to run
		// before the creature early-return below: Godlet Printer marks occupied
		// hexes as dashed, and those are exactly the ones carrying a creature,
		// so checking afterwards dropped the outline as soon as the cursor left.
		if (Array.isArray(queryOpt.hexesDashed) && queryOpt.hexesDashed.indexOf(hex) !== -1) {
			hex.displayVisualState('dashed');
			hex.grid.displayHexesGroup.bringToTop(hex.display);
			return;
		}

		if (hex.creature instanceof Creature) {
			return;
		}

		if (
			queryOpt.restoreAdjOnTransientCleanup &&
			Array.isArray(queryOpt.hexes) &&
			queryOpt.hexes.indexOf(hex) !== -1
		) {
			hex.displayVisualState('adj');
		}
	}

	clearTransientCreatureHoverVisual(creature: Creature) {
		if (!this.lastQueryOpt) {
			return;
		}

		creature.hexagons.forEach((hex) => {
			this.clearTransientHexHoverVisual(hex);
		});
	}

	/**
	 * Update overlay hexes with creature positions
	 */
	updateDisplay() {
		const activeCreature = this.game.activeCreature;
		this.allhexes.forEach((hex) => {
			const isActiveHex =
				activeCreature && hex.creature instanceof Creature && hex.creature.id === activeCreature.id;
			if (isActiveHex) {
				// Preserve the glow phase, but discard colors from the previous occupant.
				hex.cleanDisplayVisualState(
					'adj hover dashed shrunken moveRange deadzone hidden player0 player1 player2 player3',
				);
				hex.cleanOverlayVisualState(
					'hover selected reachable weakDmg moveto ownCreatureHexShade h_player0 h_player1 h_player2 h_player3',
				);
				const stalePlayerClasses = [0, 1, 2, 3]
					.filter((team) => team !== activeCreature.team)
					.map((team) => `player${team}`)
					.join(' ');
				hex.cleanOverlayVisualState(stalePlayerClasses);
			} else if (hex._markedByCrashingGlobe) {
				// Keep the target art, but remove any stale hover cursor after the
				// targeting query closes.
				hex.cleanDisplayVisualState();
				hex.cleanOverlayVisualState();
			} else {
				hex.cleanDisplayVisualState();
				hex.cleanOverlayVisualState();
			}
		});

		this.hexes.forEach((hex) => {
			hex.forEach((item) => {
				if (activeCreature && item.creature instanceof Creature) {
					if (item.creature.id == activeCreature.id) {
						// Only add if not already present to avoid stacking duplicates
						// and to avoid resetting overlay.alpha via updateStyle().
						if (
							!item.overlayClasses.includes('active') ||
							!item.overlayClasses.includes(`player${item.creature.team}`)
						) {
							item.overlayVisualState(`active creature player${item.creature.team}`);
						}
					}
				}
			});
		});
	}

	/**
	 * Test if hex exists
	 * @param {{x:number, y:number}} position - Coordinates to test
	 */
	hexExists({ x, y }: { x: number; y: number }): boolean {
		if (y >= 0 && y < this.hexes.length) {
			if (x >= 0 && x < this.hexes[y].length) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Test if hex exists inside array of hexes
	 * @param {Hex} hex - Hex to look for
	 * @param {Hex[]} hexArray - Array of hexes to look for hex in
	 */
	isHexIn(hex, hexArray) {
		for (let i = 0, len = hexArray.length; i < len; i++) {
			if (hexArray[i].x == hex.x && hexArray[i].y == hex.y) {
				return true;
			}
		}

		return false;
	}

	/**
	 * @param {number} x - Integer: Start position
	 * @param {number} y - Integer: Start position
	 * @param {number} distance - Integer: Distance from the start position
	 * @param {number} size - Integer: Creature size
	 * @param {number} id - Integer: Creature ID
	 * @returns {Hex[]} Set of the reachable hexes
	 */
	getMovementRange(x, y, distance, size, id) {
		this.cleanReachable(); // Required: resets hex.reachable flags for isWalkable correctness
		this.cleanPathAttr(true); // Erase all pathfinding data (sets hex.g = 0)

		if (distance <= 0) {
			return [];
		}

		// BFS to collect all hexes reachable within `distance` steps.
		// O(V) vs the prior O(V²) A* hack that used an impossible destination
		// to populate hex.g across the whole grid.
		const start = this.hexes[y][x];
		const visited = new Set<Hex>([start]);
		const reachable: Hex[] = [];
		let frontier: Hex[] = [start];

		for (let d = 1; d <= distance && frontier.length > 0; d++) {
			const nextFrontier: Hex[] = [];
			for (const current of frontier) {
				for (const neighbor of current.adjacentHex(1)) {
					if (visited.has(neighbor)) continue;
					visited.add(neighbor);
					if (!neighbor.isWalkable(size, id)) continue;
					neighbor.g = d;
					reachable.push(neighbor);
					nextFrontier.push(neighbor);
				}
			}
			frontier = nextFrontier;
		}

		return arrayUtils.extendToLeft(reachable, size, this.game.grid);
	}

	/**
	 * @param {number} x - Integer : 	Start position
	 * @param {number} y - Integer : 	Start position
	 * @param {number} distance - Integer : 	Distance from the start position
	 * @param {number} size - Integer : 	Creature size
	 * @param {number} id - Integer : 	Creature ID
	 * @returns {Hex[]} Set of the reachable hexes
	 */
	getFlyingRange(x, y, distance, size, id) {
		// Gather all the reachable hexes
		let hexes = this.hexes[y][x].adjacentHex(distance);

		hexes = hexes.filter((hex) => hex.isWalkable(size, id, true));

		return arrayUtils.extendToLeft(hexes, size, this.game.grid);
	}

	/**
	 * @param {number} originx - Integer : Position of the array on the grid
	 * @param {number} originy - Integer : Position of the array on the grid
	 * @param {number} offsetx - Integer : offset flipped for flipped players
	 * @param {boolean} flipped - If player is flipped or not
	 * @param {number[]} array - 2-dimensions Array containing 0 or 1 (boolean)
	 * @returns {Hex[]} Set of corresponding hexes
	 */
	getHexMap(
		originx: number,
		originy: number,
		offsetx: number,
		flipped: boolean,
		array: AugmentedMatrix,
	): Hex[] {
		// Heavy logic in here
		const hexes: Hex[] = [];

		array = array.slice(0) as AugmentedMatrix; // Copy to not modify original
		originx += flipped ? 1 - array[0].length - offsetx : -1 + offsetx;

		for (let y = 0, len = array.length; y < len; y++) {
			array[y] = array[y].slice(0); // Copy row

			// Translating to flipped pattern
			if (flipped && y % 2 != 0) {
				// Odd rows
				array[y].push(0);
			}

			// Translating even to odd row pattern
			array[y].unshift(0);
			if (originy % 2 != 0 && y % 2 != 0) {
				// Even rows
				if (flipped) {
					array[y].pop(); // Remove last element as the array will be parse backward
				} else {
					array[y].splice(0, 1); // Remove first element
				}
			}

			// Gathering hexes
			for (let x = 0; x < array[y].length; x++) {
				if (array[y][x]) {
					const xfinal = flipped ? array[y].length - 1 - x : x; // Parse the array backward for flipped player
					if (this.hexExists({ y: originy + y, x: originx + xfinal })) {
						hexes.push(this.hexes[originy + y][originx + xfinal]);
					}
				}
			}
		}

		return hexes;
	}

	showGrid(val) {
		// The coordinate view is a debug overlay, not an occlusion cue: units stay
		// fully opaque so their artwork (not a ghost) sits under the labels.
		// Only the `showGrid` state is used — never `dashed`: that state means
		// "targeting outline" and would also trigger the above-creatures
		// mirror on every occupied hex.
		this.forEachHex((hex) => {
			if (hex.creature) {
				hex.creature.clearXrayImmediately();
			}

			if (hex.drop) {
				return;
			}

			if (val) {
				hex.displayVisualState('showGrid');
			} else {
				hex.cleanDisplayVisualState('showGrid');
			}
		});
	}

	showMovementRange(creature) {
		const hexes = this.findCreatureMovementHexes(creature);

		// Block all hexes
		this.forEachHex((hex) => {
			hex.unsetReachable();
		});

		// Set reachable the given hexes
		hexes.forEach((hex) => {
			hex.setReachable();
			// Show smaller outlined hexagons for movement range visualization.
			// `moveRange` marks these as movement (not ability) outlines so the
			// renderer can apply contrast effects on dark combat backgrounds.
			hex.displayVisualState('dashed shrunken moveRange');
		});
	}

	showCurrentCreatureMovementInOverlay(creature) {
		if (!creature) {
			return;
		}
		//lastQueryOpt is same thing as used in redoQuery
		this.lastQueryOpt?.hexes?.forEach((hex) => {
			hex.overlayVisualState('reachable h_player' + creature.team);
		});
	}

	findCreatureMovementHexes(creature) {
		// maxMovement includes movement banked by abilities that store unused points.
		const movement = creature.maxMovement ?? creature.stats.movement;

		if (creature.movementType() === 'flying') {
			return this.getFlyingRange(creature.x, creature.y, movement, creature.size, creature.id);
		} else {
			return this.getMovementRange(creature.x, creature.y, movement, creature.size, creature.id);
		}
	}

	selectHexUp() {
		if (!this.hexExists({ y: this.selectedHex.y - 1, x: this.selectedHex.x })) {
			return;
		}

		if (this.selectedHex) {
			this.clearHexViewAlterations();
			this.selectedHex.onHoverOffFn(this.selectedHex);
		}

		const hex = this.hexes[this.selectedHex.y - 1][this.selectedHex.x];
		this.selectedHex = hex;
		hex.onSelectFn(hex);
	}

	selectHexDown() {
		if (!this.hexExists({ y: this.selectedHex.y + 1, x: this.selectedHex.x })) {
			return;
		}

		if (this.selectedHex) {
			this.clearHexViewAlterations();
			this.selectedHex.onHoverOffFn(this.selectedHex);
		}

		const hex = this.hexes[this.selectedHex.y + 1][this.selectedHex.x];
		this.selectedHex = hex;
		hex.onSelectFn(hex);
	}

	selectHexLeft() {
		if (!this.hexExists({ y: this.selectedHex.y, x: this.selectedHex.x - 1 })) {
			return;
		}

		if (this.selectedHex) {
			this.clearHexViewAlterations();
			this.selectedHex.onHoverOffFn(this.selectedHex);
		}

		const hex = this.hexes[this.selectedHex.y][this.selectedHex.x - 1];
		this.selectedHex = hex;
		hex.onSelectFn(hex);
	}

	selectHexRight() {
		if (!this.hexExists({ y: this.selectedHex.y, x: this.selectedHex.x + 1 })) {
			return;
		}

		if (this.selectedHex) {
			this.clearHexViewAlterations();
			this.selectedHex.onHoverOffFn(this.selectedHex);
		}

		const hex = this.hexes[this.selectedHex.y][this.selectedHex.x + 1];
		this.selectedHex = hex;
		hex.onSelectFn(hex);
	}

	confirmHex() {
		if (this.game.freezedInput) {
			return;
		}

		this.selectedHex.onConfirmFn(this.selectedHex);
	}

	/**
	 * Reset the visual state for hexes that might have been hovered, dashed, etc.
	 * Note: I'm not entirely sure what this code is doing.
	 */
	clearHexViewAlterations() {
		this.cancelDeferredActiveHexDashedClear();

		if (!this.selectedHex) {
			return;
		}

		this.redoLastQuery();
		// Clear Xray.
		this.xray(new Hex(-1, -1, null, this.game));
		// Clear Xray Queue.
		this.game.UI.xrayQueue(-1);
	}

	/**
	 * Depth for one renderable: a per-row base plus a band offset and an optional
	 * within-band slot.
	 *
	 * The bands themselves live in `src/game-display/layer.ts` so the board layout
	 * has one definition shared with the native container tree, rather than one
	 * here and a copy in the layer module.
	 */
	getDepthAtBand(y: number, band: DepthBand, slot = 0) {
		return getDepthAtBand(y, band, slot);
	}

	/**
	 * Phaser 4 owns render order through the native `depth` property; `z` is
	 * reserved for the height of a light in the lighting pipeline.
	 */
	assignSpriteDepthBand(sprite: SpriteHandle | undefined, y: number, band: DepthBand, slot = 0) {
		if (!sprite) {
			return;
		}

		sprite.setDepth(this.getDepthAtBand(y, band, slot));
	}

	orderCreatureZ() {
		const creatures = this.game.creatures;
		const traps = this.game.traps;
		const drops = this.game.drops;

		for (let y = 0, leny = this.hexes.length; y < leny; y++) {
			let groundTrapIndex = 0;
			let underEffectIndex = 0;
			let unitIndex = 0;
			let dropIndex = 0;
			let overEffectIndex = 0;
			let volumetricTrapIndex = 0;

			for (let i = 0, len = creatures.length; i < len; i++) {
				if (creatures[i] && creatures[i].y == y) {
					creatures[i].grp.setDepth(this.getDepthAtBand(y, 'UNITS', unitIndex++));
				}
			}

			for (let i = 0, len = traps.length; i < len; i++) {
				const trap = traps[i];
				if (!trap || trap.y != y) {
					continue;
				}

				const occupyingCreature = creatures.find((candidate) => {
					if (!(candidate instanceof Creature)) {
						return false;
					}
					return candidate.hexagons?.some(
						(hexagon) => hexagon.x === trap.x && hexagon.y === trap.y,
					);
				}) as Creature | undefined;
				const occupiedByOwnerCreature =
					occupyingCreature instanceof Creature && occupyingCreature === trap.ownerCreature;
				const shouldRenderOverUnits = Boolean(
					trap.typeOver || (trap.type === 'bonfire-spring' && occupiedByOwnerCreature),
				);
				if (typeof trap.syncTypeOverVisual === 'function') {
					trap.syncTypeOverVisual(shouldRenderOverUnits);
				} else if (typeof trap.setTypeOver === 'function') {
					trap.setTypeOver(shouldRenderOverUnits, false);
				}

				const visualSprites =
					typeof trap.getVisualSprites === 'function' ? trap.getVisualSprites() : [];
				for (let j = 0, visualLen = visualSprites.length; j < visualLen; j++) {
					const sprite = visualSprites[j];
					if (!sprite) {
						continue;
					}
					const isVolumetricParent =
						sprite.parent === this.trapOverGroup || sprite.parent === this.creatureGroup;
					const isCreatureLayerVolumetric = sprite.parent === this.creatureGroup;
					if (isCreatureLayerVolumetric) {
						const zReferenceCreature =
							(occupyingCreature as Creature | undefined) ??
							((trap.typeOver && trap.ownerCreature instanceof Creature && trap.ownerCreature) ||
								undefined);
						if (zReferenceCreature?.grp && typeof zReferenceCreature.grp.depth === 'number') {
							// Keep feet-volumetric tightly coupled to the occupied creature instead of
							// jumping to a global volumetric slot that can overlap unrelated units.
							sprite.setDepth(zReferenceCreature.grp.depth + (0.5 + volumetricTrapIndex++ * 0.01));
						} else {
							sprite.setDepth(this.getDepthAtBand(y, 'TRAP_VOLUMETRIC', volumetricTrapIndex++));
						}
						continue;
					}

					if (sprite === trap.display) {
						const band = isVolumetricParent ? 'TRAP_VOLUMETRIC' : 'TRAP_GROUND';
						const slot = band === 'TRAP_VOLUMETRIC' ? volumetricTrapIndex++ : groundTrapIndex++;
						this.assignSpriteDepthBand(sprite, y, band, slot);
						continue;
					}

					const band = isVolumetricParent ? 'TRAP_VOLUMETRIC' : 'EFFECT_UNDER_UNITS';
					const slot = band === 'TRAP_VOLUMETRIC' ? volumetricTrapIndex++ : underEffectIndex++;
					this.assignSpriteDepthBand(sprite, y, band, slot);
				}

				if (trap.displayOver) {
					this.assignSpriteDepthBand(trap.displayOver, y, 'TRAP_VOLUMETRIC', volumetricTrapIndex++);
				}
			}

			for (let i = 0, len = drops.length; i < len; i++) {
				if (drops[i] && drops[i].y == y && drops[i].display) {
					this.assignSpriteDepthBand(drops[i].display, y, 'DROPS', dropIndex++);
				}
			}

			if (this.materialize_overlay && this.materialize_overlay.posy == y) {
				this.assignSpriteDepthBand(
					this.materialize_overlay,
					y,
					'EFFECT_OVER_UNITS',
					overEffectIndex++,
				);
			}

			if (this.secondary_overlay && this.secondary_overlay.posy == y) {
				this.assignSpriteDepthBand(
					this.secondary_overlay,
					y,
					'EFFECT_OVER_UNITS',
					overEffectIndex++,
				);
			}
		}

		// Ascending depth: lower depth draws first, i.e. further back. These were
		// `sort('depth', -1)` calls, whose `-1` was inert under Phaser 2's renderer
		// (list order did not affect drawing) but would invert the board if it were
		// honoured now, so the direction is stated explicitly instead.
		sortLayerByDepth(this.trapGroup);
		sortLayerByDepth(this.creatureGroup);
		sortLayerByDepth(this.dropGroup);
		sortLayerByDepth(this.trapOverGroup);
	}

	/**
	 * Immediately removes all xray effects without re-applying ghostOverlap for
	 * any creature. Use this at turn boundaries so the old active creature's
	 * obstructors fade to zero cleanly before the next unit's ghostOverlap runs.
	 */
	clearAllXray(immediate = false) {
		this.lastXrayHex = null;
		this.game.creatures.forEach((c) => {
			if (!(c instanceof Creature)) {
				return;
			}
			if (immediate) {
				c.clearXrayImmediately();
				return;
			}
			c.xray(false);
		});
	}

	/**
	 * Re-evaluate which creatures visually obstruct the active creature and
	 * update their xray state accordingly. Called after every hex step during
	 * movement so the effect stays correct as the unit changes rows.
	 */
	refreshActiveCreatureXray() {
		if (this.game.animations?.xraySuppressed) return;
		const { activeCreature } = this.game;
		if (!(activeCreature instanceof Creature)) return;
		this.game.creatures.forEach((c) => {
			if (c instanceof Creature) c.xray(false);
		});
		activeCreature.hexagons.forEach((h) => h.ghostOverlap(activeCreature));
	}

	//******************//
	//Shortcut functions//
	//******************//

	/**
	 * Execute f for each hexes
	 * @param {function} func - Function to execute
	 * @deprecated use this.allhexes.forEach(fn)
	 */
	forEachHex(func: (hex: Hex) => void) {
		this.hexes.forEach((hex) => {
			hex.forEach(func);
		});
	}

	/**
	 * Execute hex.cleanPathAttr() function for all the grid. Refer to the Hex class for more info
	 * @param {boolean} includeG - Include hex.g attribute
	 * @deprecated use this.allhexes.forEach(hex => hex.cleanPathAttr(includeG))
	 */
	cleanPathAttr(includeG) {
		this.allhexes.forEach((hex) => hex.cleanPathAttr(includeG));
	}

	/**
	 * Execute hex.setReachable() function for all the grid. Refer to the Hex class for more info
	 * @deprecated use this.allhexes.forEach(hex => hex.setReachable())
	 */
	cleanReachable() {
		this.allhexes.forEach((hex) => hex.setReachable());
	}

	/**
	 * Draw a preview of the creature at the given coordinates
	 * @param {{x:number, y:number}} pos - Coordinates {x,y}
	 * @param {object} creatureData - Object containing info from the database (game.retrieveCreatureStats)
	 */
	previewCreature(pos, creatureData, player, secondary = false) {
		const game = this.game;
		const clearPreviewOverlay = (preview) => {
			if (!preview) {
				return;
			}

			clearPreviewTweens(game, preview);
			preview.alpha = 0;

			if (preview._previewPos === undefined) {
				return;
			}

			for (let i = 0, prevSize = preview._previewSize; i < prevSize; i++) {
				const prevHex = this.hexes[preview._previewPos.y]?.[preview._previewPos.x - i];
				if (prevHex && prevHex.creature !== game.activeCreature) {
					this.cleanHex(prevHex);
					this.restoreReachableHexVisual(prevHex);
				}
			}

			preview._previewPos = undefined;
		};

		const shouldShowPlacementPreview =
			!game.isReplayInProgress &&
			!game.botController?.isBotTurn() &&
			!!game.activeCreature &&
			game.activePlayer === game.activeCreature.player;

		if (!shouldShowPlacementPreview) {
			clearPreviewOverlay(secondary ? this.secondary_overlay : this.materialize_overlay);
			return;
		}

		const targetHex = this.hexes[pos.y]?.[pos.x];
		const queryHexes = this.lastQueryOpt?.hexes;
		if (
			!targetHex ||
			(Array.isArray(queryHexes) &&
				queryHexes.length > 0 &&
				(!targetHex.reachable || queryHexes.indexOf(targetHex) === -1))
		) {
			clearPreviewOverlay(secondary ? this.secondary_overlay : this.materialize_overlay);
			return;
		}

		const hex = this.hexes[pos.y][pos.x - (creatureData.size - 1)];
		const originX =
			creatureData.display['offset-x'] +
			(creatureData.type == '--' ? getDarkPriestDisplayOffsetX(player) : 0);
		const cardboard =
			creatureData.type == '--' ? getDarkPriestCardboardKey(player) : creatureData.name;

		// The cardboard is what the preview measures the unit against, so it is
		// also what triggers its download. It is a few KiB and normally arrives
		// long before the player settles on a hex, but a unit summoned straight
		// from an ability (Dark Priest, Uncle Fungus, Scavenger) can reach a
		// preview cold. When that happens, hold the request and replay the newest
		// one for this overlay once the texture lands, rather than drawing a
		// ghost sized against a missing texture.
		if (!isTextureReady(cardboard)) {
			// Recorded before the request, so a loader that answers synchronously
			// still finds the request to replay.
			setPendingPreview(this, secondary ? 'secondary' : 'primary', {
				pos,
				creatureData,
				player,
				secondary,
			});
			clearPreviewOverlay(secondary ? this.secondary_overlay : this.materialize_overlay);
			ensureCardboard(cardboard, () => replayPendingPreview(this, secondary));
			return;
		}
		clearPendingPreview(this, secondary);

		if (!secondary) {
			if (!this.materialize_overlay) {
				// If sprite does not exist
				// Adding sprite
				this.materialize_overlay = this.game.gameEngine.add.sprite(
					0,
					0,
					cardboard,
					undefined,
					this.creatureGroup,
				);
				this.materialize_overlay.setOrigin(0.5, 1);
				this.materialize_overlay.posy = pos.y;
				// A freshly created sprite keeps depth 0, which renders it behind
				// every creature and trap on the board. orderCreatureZ() only
				// re-bands an overlay when its row changes, so a brand new ghost
				// has to be slotted into its depth band explicitly.
				this.orderCreatureZ();
			} else {
				this.materialize_overlay.setTexture(cardboard);
				if (this.materialize_overlay.posy != pos.y) {
					this.materialize_overlay.posy = pos.y;
					this.orderCreatureZ();
				}
			}
		} else {
			if (!this.secondary_overlay) {
				// If sprite does not exists
				// Adding sprite
				this.secondary_overlay = this.game.gameEngine.add.sprite(
					0,
					0,
					cardboard,
					undefined,
					this.creatureGroup,
				);
				this.secondary_overlay.setOrigin(0.5, 1);
				this.secondary_overlay.posy = pos.y;
				// Same as the primary overlay: slot the new sprite into its band.
				this.orderCreatureZ();
			} else {
				this.secondary_overlay.setTexture(cardboard);
				if (this.secondary_overlay.posy != pos.y) {
					this.secondary_overlay.posy = pos.y;
					this.orderCreatureZ();
				}
			}
		}

		const preview = secondary ? this.secondary_overlay : this.materialize_overlay;

		// Placing sprite. Mirrors CreatureSprite's placement so the ghost lines
		// up with the unit it is previewing — including reading the frame size
		// rather than the source size, for the same reason.
		const previewSize = getFrameSize(preview);
		preview.x =
			hex.displayPos.x +
			(!player.flipped ? originX : HEX_WIDTH_PX * creatureData.size - previewSize.width - originX) +
			previewSize.width / 2;
		preview.y = hex.displayPos.y + creatureData.display['offset-y'] + previewSize.height;
		// The ghost is the overlay's final say on its own opacity: whatever fade
		// the previous use left behind has to be gone before it is pinned.
		clearPreviewTweens(game, preview);

		// Held at a fixed ghost opacity, never tweened. The preview used to
		// flicker (0.5 → 0.15, yoyo, forever), but under Phaser 4 the tween only
		// completed one cycle before Phaser tore it down — `tweens.add()` resets
		// a tween the moment it is created, which is before the chained
		// `repeat(-1)` could be applied, so the loop counter stayed at 0 and
		// `nextState()` completed the tween after the first pass. Every hex the
		// cursor then crossed restarted that single fade, so moving between hexes
		// animated the ghost instead of holding it still.
		preview.alpha = GHOST_PREVIEW_ALPHA;

		if (player.flipped) {
			preview.setScale(-1, 1);
		} else {
			preview.setScale(1, 1);
		}

		// Clean overlay from the previous preview position before painting the new one.
		// Without this, every hex the cursor passes over accumulates the creature-selected
		// overlay, making it look like multiple creatures have been materialized at once.
		// After cleaning, restore the reachable visual state so the hex stays filled like
		// the rest of the spawn-range hexes (redoLastQuery may have already restored it).
		if (preview._previewPos !== undefined) {
			for (let i = 0, prevSize = preview._previewSize; i < prevSize; i++) {
				const prevHex = this.hexes[preview._previewPos.y]?.[preview._previewPos.x - i];
				if (prevHex) {
					if (prevHex.creature === game.activeCreature) {
						continue;
					}
					this.cleanHex(prevHex);
					this.restoreReachableHexVisual(prevHex);
				}
			}
		}

		for (let i = 0, size = creatureData.size; i < size; i++) {
			const hexInstance = this.hexes[pos.y][pos.x - i];
			this.cleanHex(hexInstance);
			hexInstance.overlayVisualState('creature selected player' + game.activeCreature.team);
		}

		preview._previewPos = { x: pos.x, y: pos.y };
		preview._previewSize = creatureData.size;
	}

	/**
	 * Internal debugging method to log and visually highlight (in blue) an array
	 * of hexes.
	 * @param {Hex[]} hexes - Hexes to log and visually highlight.
	 */
	__debugHexes(hexes: Hex[]) {
		if (DEBUG) {
			console.debug({ hexes }, hexes.map((hex) => hex.coord).join(', '));
			hexes.forEach((hex) => hex.displayVisualState('creature selected player1'));
		}
	}

	fadeOutTempCreature(target = this.materialize_overlay, durationMs = 500) {
		// TODO: factor out this function. Use either Creature.creatureSprite
		// or the existing temp creature created by /src/abilities/Dark-Priest.js
		if (target) {
			// A fade already in flight (a cancelled summon, a second
			// materialization) would fight this one for `alpha`.
			clearPreviewTweens(this.game, target);
			// Snap to the ghost opacity the preview was held at, so the handoff to
			// the materializing unit — which fades up from the very same value —
			// has no seam.
			target.alpha = GHOST_PREVIEW_ALPHA;
			this.game.gameEngine
				.tween(target)
				.to(
					{
						alpha: 0,
					},
					durationMs,
					Easing.Linear.None,
				)
				.start();
		}
	}
}
