import { throttle } from 'underscore';
import { Creature } from '../creature';
import { isQueueEvent, type EventQueue, type QueueEntry, type QueueEvent } from '../event_queue';
import { getAvatarSet } from '../style/avatar-styles';
import { getUrl } from '../assets';

const CONST = {
	animDurationMS: 500,
	queueLeapHeightPx: 60,
	queueLeapSegments: 8,
};

export class Queue {
	private element: HTMLElement;
	private vignettes: Array<Vignette>;
	private eventHandlers: QueueEventHandlers;
	private delayPreviewEl: HTMLElement | null = null;
	private layoutKey: string;

	static IMMEDIATE = 1;

	constructor(queueElement: HTMLElement, eventHandlers: QueueEventHandlers = {}) {
		this.element = queueElement;
		this.element.innerHTML = '';
		this.vignettes = [];
		this.eventHandlers = eventHandlers;
		this.layoutKey = this.getLayoutKey();
	}

	setQueue(eventQueue: EventQueue, turnNumber: number) {
		const nextVignettes = Queue.getNextVignettes(
			eventQueue.queue,
			eventQueue.nextQueue,
			turnNumber,
			this.eventHandlers,
		);
		this.setVignettes(nextVignettes);
	}

	refresh() {
		this.vignettes.forEach((v) => v.refresh());
	}

	resize() {
		const layoutKey = this.getLayoutKey();
		if (layoutKey === this.layoutKey) {
			return;
		}
		this.layoutKey = layoutKey;
		this.clearDelayPreview();
		let x = 0;
		this.vignettes.forEach((v, index) => {
			v.pendingActivationAnimation?.cancel();
			v.pendingActivationAnimation = null;
			v.el.getAnimations().forEach((animation) => animation.cancel());
			v.previousQueueX = -1;
			v.update(index, x);
			v.el.getAnimations().forEach((animation) => animation.finish());
			x += v.getWidth();
		});
	}

	private getLayoutKey() {
		if (window.matchMedia('(orientation: landscape) and (max-height: 512px)').matches) {
			return window.matchMedia('(max-height: 319px)').matches ? 'compact-small' : 'compact';
		}
		return window.matchMedia('(orientation: portrait) and (max-width: 600px)').matches
			? 'portrait'
			: 'desktop';
	}

	empty(immediately: number) {
		this.clearDelayPreview();
		if (immediately === Queue.IMMEDIATE) {
			this.vignettes = [];
			this.element.innerHTML = '';
		} else {
			this.setVignettes([]);
		}
	}

	xray(creatureId: number) {
		this.vignettes.forEach((v) => v.xray(creatureId));
	}

	bounce(creatureId: number, bounceHeight = 40) {
		Queue.throttledBounce(this.vignettes, creatureId, bounceHeight);
	}

	showDelayPreview() {
		this.clearDelayPreview();

		const activeVignette = this.vignettes.find(
			(v) => CreatureVignette.is(v) && (v as CreatureVignette).isActiveCreature,
		) as CreatureVignette | undefined;

		if (!activeVignette) {
			return;
		}

		const insertAt = this.getDelayPreviewIndex(activeVignette, this.vignettes);
		const x = this.vignettes
			.slice(0, insertAt)
			.reduce((position, vignette) => position + vignette.getWidth(), 0);

		const marker = document.createElement('div');
		marker.setAttribute('aria-hidden', 'true');
		marker.className = 'delay-preview delay-preview-marker';
		marker.style.zIndex = '999';
		marker.style.transform = `translateX(${x}px) translateY(0px) scale(1)`;

		this.delayPreviewEl = marker;
		this.element.appendChild(marker);
	}

	clearDelayPreview() {
		if (this.delayPreviewEl) {
			this.delayPreviewEl.remove();
			this.delayPreviewEl = null;
		}
	}

	private setVignettes(nextVignettes: Vignette[]) {
		this.clearDelayPreview();
		const prevVs = this.vignettes;
		this.vignettes = Queue.reuseOldDomElements(prevVs, nextVignettes);
		const nextHashes = new Set(this.vignettes.map((v) => v.getHash()));
		if (prevVs.some((v) => TurnEndMarkerVignette.is(v) && !nextHashes.has(v.getHash()))) {
			const first = this.vignettes[0];
			if (first instanceof CreatureVignette) {
				first.activatingAfterRoundMarker = true;
				if (first.previousQueueX > 100) {
					const width = first.getQueuedWidth();
					this.vignettes.slice(1).forEach((v) => {
						if (v instanceof CreatureVignette && v.previousQueueX >= 0) {
							v.roundHandoff = { width };
						}
					});
				}
			}
		}
		Queue.deleteRemovedVignettes(this.vignettes, prevVs);
		Queue.insertUpdateNextVignettes(this.vignettes, prevVs, this.element);
	}

	private getDelayPreviewIndex(activeVignette: CreatureVignette, vignettes: Vignette[]) {
		const delayedCreatureIndex = vignettes.findIndex((v) => {
			if (!CreatureVignette.is(v)) {
				return false;
			}

			const creatureVignette = v as CreatureVignette;
			return (
				creatureVignette.turnNumberIsCurrentTurn &&
				creatureVignette.creature.isDelayed &&
				activeVignette.creature.getInitiative() > creatureVignette.creature.getInitiative()
			);
		});

		if (delayedCreatureIndex >= 0) {
			return delayedCreatureIndex;
		}

		const lastDelayedCreatureIndex = utils.findLastIndex(vignettes, (v) => {
			return (
				CreatureVignette.is(v) &&
				(v as CreatureVignette).turnNumberIsCurrentTurn &&
				(v as CreatureVignette).creature.isDelayed
			);
		});

		if (lastDelayedCreatureIndex >= 0) {
			return lastDelayedCreatureIndex + 1;
		}

		const turnEndIndex = vignettes.findIndex((v) => TurnEndMarkerVignette.is(v));
		return turnEndIndex >= 0 ? turnEndIndex : vignettes.length;
	}

	private static throttledBounce = throttle(
		(vignettes: Vignette[], creatureId: number, bounceHeight: number) => {
			let x = 0;
			vignettes.forEach((v, i) => {
				v.bounce(creatureId, i, x, bounceHeight);
				x += v.getWidth();
			});
		},
		500,
	);

	private static getNextVignettes(
		entries: QueueEntry[],
		entriesNext: QueueEntry[],
		turnNum: number,
		eventHandlers: QueueEventHandlers,
	) {
		const isDelayed = (entry: QueueEntry, isNextQueue: boolean) =>
			isQueueEvent(entry)
				? Boolean(entry.delayed)
				: isNextQueue
				? Boolean(entry.isDelayedInNextQueue)
				: entry.isDelayed;
		const undelayedCurr = entries.filter((entry) => !isDelayed(entry, false));
		const delayedCurr = entries.filter((entry) => isDelayed(entry, false));
		const undelayedNext = entriesNext.filter((entry) => !isDelayed(entry, true));
		const delayedNext = entriesNext.filter((entry) => isDelayed(entry, true));

		const newVignette = (
			entry: QueueEntry,
			turnNumber: number,
			isCurrentTurn: boolean,
			isActive: boolean,
		): Vignette => {
			if (isQueueEvent(entry)) {
				return new EventVignette(entry, eventHandlers, isActive);
			}

			const isAlreadyShown = isCurrentTurn
				? false
				: entries.some((oldEntry) => !isQueueEvent(oldEntry) && oldEntry.id === entry.id);
			return new CreatureVignette(
				entry,
				turnNumber,
				eventHandlers,
				isActive,
				isCurrentTurn,
				isAlreadyShown,
			);
		};
		const mapEntries = (queueEntries: QueueEntry[], turnNumber: number, current: boolean) =>
			queueEntries.map((entry, index) =>
				newVignette(entry, turnNumber, current, current && index === 0),
			);

		const undelayedVsCurr = mapEntries(undelayedCurr, turnNum, true);
		const delayMarkerVCurr = delayedCurr.length
			? [new DelayMarkerVignette(turnNum, eventHandlers)]
			: [];
		const delayedVsCurr = mapEntries(delayedCurr, turnNum, true);

		const turnEndMarkerV = [new TurnEndMarkerVignette(turnNum, eventHandlers)];

		const undelayedVsNext = mapEntries(undelayedNext, turnNum + 1, false);
		const delayMarkerVNext = delayedNext.length
			? [new DelayMarkerVignette(turnNum + 1, eventHandlers)]
			: [];
		const delayedVsNext = mapEntries(delayedNext, turnNum + 1, false);
		const vsNext = [].concat(turnEndMarkerV, undelayedVsNext, delayMarkerVNext, delayedVsNext);

		/**
		 * NOTE: There are special cases when delayed creatures are at the front of the queue.
		 * -
		 * DEFAULT CASE - undelayed creatures > 0
		 * (not delayed, active) (delayed) (delayed) ...
		 * becomes:
		 * (not delayed, active) (delay marker) (delayed) (delayed) ...
		 * i.e., delay marker is in front of delayed creatures
		 * -
		 * SPECIAL CASE 1 - num undelayed creatures === 0, num delayed creatures > 1
		 * (delayed, active) (delayed) (delayed) ...
		 * becomes:
		 * (delayed, active) (delay marker) (delayed) (delayed) ...
		 * i.e., delay marker is behind first delayed creature
		 * -
		 * SPECIAL CASE 2 - num undelayed creatures === 0, num delayed creatures === 1
		 * (delayed, active) (turn end marker) ...
		 * becomes:
		 * (delayed, active) (turn end marker) ...
		 * i.e., no delayed marker
		 */

		if (undelayedVsCurr.length === 0 && delayedVsCurr.length > 1) {
			// NOTE: Special case 1
			const firstV = [delayedVsCurr.shift()];
			return [].concat(firstV, delayMarkerVCurr, delayedVsCurr, vsNext);
		} else if (undelayedVsCurr.length === 0 && delayedVsCurr.length === 1) {
			// NOTE: Special case 2
			return [].concat(delayedVsCurr, vsNext);
		}
		// NOTE: All other cases
		return [].concat(undelayedVsCurr, delayMarkerVCurr, delayedVsCurr, vsNext);
	}

	private static reuseOldDomElements(oldVignettes: Vignette[], newVignettes: Vignette[]) {
		/**
		 * NOTE: For every vignette in newVignettes, if there's
		 * an equivalent in oldVignettes, use its DOM element.
		 * This keeps animations, transitions, and styles from breaking.
		 */
		const oldVDict = utils.arrToDict(oldVignettes, (v: Vignette) => v.getHash());
		for (const newV of newVignettes) {
			const hash = newV.getHash();
			if (oldVDict.hasOwnProperty(hash)) {
				oldVDict[hash].pendingActivationAnimation?.cancel();
				newV.el = oldVDict[hash].el;
				// Keep the rendered X coordinate, not a gameplay-specific delay flag.
				// Anything that actually moves this avatar backwards in the current
				// turn should take the same visual path, including forced abilities.
				newV.previousQueueX = oldVDict[hash].xPosition;
			}
		}

		return newVignettes;
	}

	private static deleteRemovedVignettes(nextVignettes: Vignette[], prevVignettes: Vignette[]) {
		const nextHashes = new Set(nextVignettes.map((v) => v.getHash()));
		const vignettesDeletedAtFront = utils.takeWhile(
			prevVignettes,
			(v: Vignette) => !nextHashes.has(v.getHash()),
		);
		const spaceDeletedAtFrontOfQueue = vignettesDeletedAtFront.reduce(
			(acc, v) => acc + v.getWidth(),
			0,
		);
		const frontDeletedHashes = new Set(vignettesDeletedAtFront.map((v) => v.getHash()));
		const outgoing = vignettesDeletedAtFront[0];
		const marker = vignettesDeletedAtFront[1];
		if (
			outgoing instanceof CreatureVignette &&
			outgoing.isActiveCreature &&
			marker instanceof TurnEndMarkerVignette
		) {
			outgoing.followingRoundMarkerWidth = marker.getWidth();
		}

		let x = 0;
		prevVignettes.forEach((v, i) => {
			const hash = v.getHash();
			const w = v.getWidth();
			if (!nextHashes.has(hash)) {
				if (frontDeletedHashes.has(hash)) {
					v.deleteFromFront(i, x, spaceDeletedAtFrontOfQueue);
				} else {
					v.delete(i, x);
				}
			}
			x += w;
		});
	}

	private static insertUpdateNextVignettes(
		nextVignettes: Vignette[],
		prevVignettes: Vignette[],
		containerElement: HTMLElement,
	) {
		const prevHashes = new Set(prevVignettes.map((v) => v.getHash()));
		const nextHashes = new Set(nextVignettes.map((v) => v.getHash()));
		const [updateHashes, insertHashes] = utils.splitSetBy(nextHashes, (h: string) =>
			prevHashes.has(h),
		);

		let x = 0;
		nextVignettes.forEach((v, i) => {
			const hash = v.getHash();
			if (insertHashes.has(hash)) {
				v.insert(containerElement, i, x);
				x += v.getWidth();
			} else if (updateHashes.has(hash)) {
				v.update(i, x);
				x += v.getWidth();
			}
		});
	}
}

class Vignette {
	pendingActivationAnimation: Animation | null = null;
	queuePosition = -1;
	xPosition = -1;
	previousQueueX = -1;
	turnNumber = -1;
	el: HTMLElement;
	eventHandlers: QueueEventHandlers = {};

	getHash() {
		return 'none';
	}

	getHTML() {
		return `<div></div>`;
	}

	insert(containerElement: HTMLElement, queuePosition: number, x: number) {
		this.queuePosition = queuePosition;
		this.xPosition = x;
		if (this.el) {
			this.el.remove();
		}

		const tmp = document.createElement('div');
		tmp.innerHTML = this.getHTML();
		this.el = tmp.firstChild as HTMLElement;
		containerElement.appendChild(this.el);

		this.addEvents();
		this.animateInsert(queuePosition, x);
		return this;
	}

	update(queuePosition: number, x: number) {
		this.queuePosition = queuePosition;
		this.xPosition = x;
		this.animateUpdate(queuePosition, x);
		return this;
	}

	delete(queuePosition: number, x: number) {
		this.queuePosition = queuePosition;
		this.animateDelete(queuePosition, x).onfinish = () => {
			this.el.remove();
		};
		return this;
	}

	deleteFromFront(queuePosition: number, x: number, spaceDeletedAtFrontOfQueue: number) {
		this.queuePosition = queuePosition;
		this.animateDeleteFromFront(queuePosition, x, spaceDeletedAtFrontOfQueue).onfinish = () => {
			this.el.remove();
		};
		return this;
	}

	animateInsert(queuePosition: number, x: number) {
		const keyframes = [
			{
				transform: `translateX(${x + 500}px) translateY(-100px) scale(1)`,
				easing: 'ease-out',
			},
			{
				transform: `translateX(${x + 500}px) translateY(0px) scale(1)`,
				easing: 'ease-in',
				offset: 0.3,
			},
			{ transform: `translateX(${x}px) translateY(0px) scale(1)` },
		];
		const animation = this.el.animate(keyframes, {
			duration: CONST.animDurationMS,
			fill: 'forwards',
		});
		animation.commitStyles();
		return animation;
	}

	animateUpdate(queuePosition: number, x: number) {
		const keyframes = [{ transform: `translateX(${x}px) translateY(0px) scale(1)` }];
		const animation = this.el.animate(keyframes, {
			duration: CONST.animDurationMS,
			fill: 'forwards',
		});
		animation.commitStyles();
		return animation;
	}

	animateDelete(queuePosition: number, x: number) {
		const keyframes = [{ transform: `translateX(${x}px) translateY(-100px) scale(1)` }];
		const animation = this.el.animate(keyframes, {
			duration: CONST.animDurationMS,
			fill: 'forwards',
		});
		animation.commitStyles();
		return animation;
	}

	animateDeleteFromFront(queuePosition: number, x: number, emptySpaceAtFrontOfQueue: number) {
		const keyframes = [
			{ transform: `translateX(${x - emptySpaceAtFrontOfQueue}px) translateY(0px) scale(1)` },
		];
		const animation = this.el.animate(keyframes, {
			duration: CONST.animDurationMS,
			fill: 'forwards',
		});
		animation.commitStyles();
		return animation;
	}

	animateBounce(queuePosition: number, x: number, bounceH: number) {
		const NUM_BOUNCES = 3;
		const BOUNCE_MS = 280 * NUM_BOUNCES;

		const scale = queuePosition === 0 ? 1.25 : 1.0;
		const restingKeyframe = { transform: `translateX(${x}px) translateY(0px) scale(${scale})` };
		const bounceHs = new Array(NUM_BOUNCES)
			.fill(0)
			.map((_, i) => bounceH * Math.pow(1 / (i + 1), 2));
		const keyframes = [restingKeyframe];
		for (const bounceH of bounceHs) {
			keyframes.push({
				transform: `translateX(${x}px) translateY(${-bounceH}px) scale(${scale})`,
			});
			keyframes.push(restingKeyframe);
		}

		const animation = this.el.animate(keyframes, { duration: BOUNCE_MS });
		animation.commitStyles();
		return animation;
	}

	getWidth() {
		return 80;
	}

	/* eslint-disable @typescript-eslint/no-unused-vars */
	xray(creatureId: number) {
		// pass
	}

	bounce(creatureId: number, i: number, x: number, bounceHeight: number) {
		// pass
	}
	/* eslint-enable @typescript-eslint/no-unused-vars */

	addEvents() {
		// pass
	}

	refresh() {
		// pass
	}
}

class CreatureVignette extends Vignette {
	followingRoundMarkerWidth: number | null = null;
	roundHandoff: { width: number } | null = null;
	activatingAfterRoundMarker = false;
	creature: Creature;
	isActiveCreature: boolean;
	turnNumberIsCurrentTurn: boolean;
	isAlreadyShown: boolean;

	constructor(
		creature: Creature,
		turnNumber: number,
		eventHandlers: QueueEventHandlers,
		isActiveCreature = false,
		turnNumberIsCurrentTurn = true,
		isAlreadyShown = false,
	) {
		super();
		this.creature = creature;
		this.turnNumber = turnNumber;
		this.eventHandlers = eventHandlers;
		this.isActiveCreature = isActiveCreature;
		this.turnNumberIsCurrentTurn = turnNumberIsCurrentTurn;
		this.isAlreadyShown = isAlreadyShown;
	}

	getHash() {
		const id = 'id' + this.creature.id;
		return `creature_${id}_turn${this.turnNumber}`;
	}

	getHTML() {
		const c = this.creature;
		const set = getAvatarSet(c.type);
		const controllerClass = c.player.controller === 'bot' ? ' bot' : '';
		const classes = ['vignette', 'creature', 'type' + c.type, 'p' + c.team].join(' ');
		return `<div creatureid="${c.id}" class="${classes}${controllerClass}" data-set="${set}">
				<div class="frame"></div>
				<div class="overlay_frame"></div>
				<div class="delay_frame"></div>
				<div class="stats"></div>
			</div>`;
	}

	setCreature(creature: Creature) {
		this.creature = creature;
	}

	insert(containerElement: HTMLElement, queuePosition: number, x: number) {
		super.insert(containerElement, queuePosition, x);
		this.updateDOM();
		return this;
	}

	update(queuePosition: number, x: number) {
		this.queuePosition = queuePosition;
		this.xPosition = x;
		if (this.roundHandoff && !this.isActiveCreature) {
			const { width } = this.roundHandoff;
			const duration = CONST.animDurationMS;
			const offset = x - 100;
			this.updateDOM();
			const animation = this.el.animate(
				[{ transform: `translateX(${100 + width + offset}px) translateY(0px) scale(1)` }],
				{ duration, fill: 'forwards' },
			);
			this.pendingActivationAnimation = animation;
			animation.onfinish = () => {
				animation.commitStyles();
				animation.cancel();
				this.pendingActivationAnimation = null;
				const frames = Array.from({ length: 9 }, (_, i) => {
					const p = i / 8;
					const leaderRight = 100 * (1 - p) + (width + (80 - width) * p) * (1 + 0.25 * p);
					return {
						transform: `translateX(${leaderRight + offset}px) translateY(0px) scale(1)`,
						offset: p,
					};
				});
				this.el.animate(frames, { duration: CONST.animDurationMS, fill: 'forwards' });
			};
			return this;
		}
		if (this.activatingAfterRoundMarker && this.previousQueueX > 100 && this.isActiveCreature) {
			const duration = CONST.animDurationMS;
			const animation = this.el.animate(
				[{ transform: 'translateX(100px) translateY(0px) scale(1)' }],
				{ duration, fill: 'forwards' },
			);
			this.pendingActivationAnimation = animation;
			animation.onfinish = () => {
				animation.commitStyles();
				animation.cancel();
				this.pendingActivationAnimation = null;
				this.activateAndAnimate(queuePosition, x);
			};
			return this;
		}
		this.activateAndAnimate(queuePosition, x);
		return this;
	}

	private activateAndAnimate(queuePosition: number, x: number) {
		const enteringActive = this.isActiveCreature && !this.el.classList.contains('active');
		const style = window.getComputedStyle(this.el);
		const before = {
			width: style.width,
			height: style.height,
			marginTop: style.marginTop,
		};
		this.updateDOM();
		this.animateUpdate(queuePosition, x);
		if (enteringActive) {
			const target = window.getComputedStyle(this.el);
			this.el.animate(
				[before, { width: target.width, height: target.height, marginTop: target.marginTop }],
				{ duration: CONST.animDurationMS },
			);
		}
	}

	private updateDOM() {
		const cl = this.el.classList;

		if (this.isActiveCreature) {
			cl.add('active');
		} else {
			cl.remove('active');
		}

		if (this.creature.temp) {
			cl.add('unmaterialized');
			cl.remove('materialized');
		} else {
			cl.remove('unmaterialized');
			cl.add('materialized');
		}

		if (this.creature.isDelayed && this.turnNumberIsCurrentTurn) {
			cl.add('delayed');
		}

		this.el.style.zIndex = this.creature.temp ? '1000' : this.queuePosition + 1 + '';

		const stats = this.isAlreadyShown ? 'Queued' : this.creature.fatigueText;
		const statsClasses = ['stats', utils.toClassName(stats)].join(' ');
		const statsEl = this.el.querySelector('div.stats');
		statsEl.className = statsClasses;
		statsEl.textContent = stats;
	}

	animateInsert(queuePosition: number, x: number) {
		const scale = this.isActiveCreature ? 1.25 : 1.0;
		const keyframes = [
			{
				transform: `translateX(${x + 500}px) translateY(-100px) scale(${scale})`,
				easing: 'ease-out',
			},
			{
				transform: `translateX(${x + 500}px) translateY(0px) scale(${scale})`,
				easing: 'ease-in',
				offset: 0.3,
			},
			{ transform: `translateX(${x}px) translateY(0px) scale(${scale})` },
		];
		const animation = this.el.animate(keyframes, {
			duration: CONST.animDurationMS,
			fill: 'forwards',
		});
		animation.commitStyles();
		return animation;
	}

	animateUpdate(queuePosition: number, x: number) {
		const scale = this.isActiveCreature ? 1.25 : 1.0;

		if (this.isMovingBackInCurrentTurn(x)) {
			return this.animateQueueLeap(x, scale);
		}

		const keyframes = [{ transform: `translateX(${x}px) translateY(0px) scale(${scale})` }];
		const animation = this.el.animate(keyframes, {
			duration: CONST.animDurationMS,
			fill: 'forwards',
		});
		animation.commitStyles();
		return animation;
	}

	/**
	 * Detect the visual transition itself rather than how gameplay caused it.
	 * Voluntary delay, Knightmare/Stomper-style forced delay, and any future
	 * same-turn mechanic that pushes an avatar backwards should read the same.
	 */
	private isMovingBackInCurrentTurn(x: number) {
		return this.turnNumberIsCurrentTurn && this.previousQueueX >= 0 && x > this.previousQueueX;
	}

	/**
	 * Follow a horizontal parabola from the previous queue slot to the new one.
	 * X progresses across the whole animation, while Y reaches its apex at the
	 * midpoint instead of forming the old two-segment triangle.
	 */
	private animateQueueLeap(x: number, scale: number) {
		const startX = this.previousQueueX;
		const keyframes = Array.from({ length: CONST.queueLeapSegments + 1 }, (_, index) => {
			const progress = index / CONST.queueLeapSegments;
			const frameX = startX + (x - startX) * progress;
			const frameY = -4 * CONST.queueLeapHeightPx * progress * (1 - progress);
			return {
				transform: `translateX(${frameX}px) translateY(${frameY}px) scale(${scale})`,
				offset: progress,
			};
		});
		const animation = this.el.animate(keyframes, {
			duration: CONST.animDurationMS,
			easing: 'linear',
			fill: 'forwards',
		});
		animation.commitStyles();
		return animation;
	}

	animateDelete(queuePosition: number, x: number) {
		if (this.creature.dead) {
			return this.animateKill(x);
		}
		this.el.style.zIndex = '-1';
		const [x_, y, scale] = this.isActiveCreature ? [-this.getWidth(), 0, 1.25] : [x, -100, 1];
		const keyframes = [{ transform: `translateX(${x_}px) translateY(${y}px) scale(${scale})` }];
		const animation = this.el.animate(keyframes, {
			duration: CONST.animDurationMS,
			fill: 'forwards',
		});
		animation.commitStyles();
		return animation;
	}

	animateDeleteFromFront(queuePosition: number, x: number, emptySpaceAtFrontOfQueue: number) {
		if (this.creature.dead) {
			return this.animateKill(x);
		}
		const scale = this.isActiveCreature ? 1.25 : 1;
		if (this.followingRoundMarkerWidth !== null) {
			const animation = this.el.animate(
				[
					{ transform: `translateX(${x}px) translateY(0px) scale(${scale})`, offset: 0 },
					{
						transform: `translateX(${
							this.followingRoundMarkerWidth * 0.7 - 100
						}px) translateY(0px) scale(${scale})`,
						offset: 0.3,
					},
					{ transform: `translateX(-100px) translateY(0px) scale(${scale})`, offset: 1 },
				],
				{ duration: CONST.animDurationMS, fill: 'forwards' },
			);
			animation.commitStyles();
			return animation;
		}
		const keyframes = [
			{
				transform: `translateX(${x - emptySpaceAtFrontOfQueue}px) translateY(0px) scale(${scale})`,
			},
		];
		const animation = this.el.animate(keyframes, {
			duration: CONST.animDurationMS,
			fill: 'forwards',
		});
		animation.commitStyles();
		return animation;
	}

	private animateKill(x: number) {
		const scale = this.isActiveCreature ? 1.25 : 1;
		const keyframes = [
			{
				transform: `translateX(${x}px) translateY(0px) scale(${scale})`,
				easing: 'ease-out',
				offset: 0,
			},
			{
				transform: `translateX(${x}px) translateY(-80px) scale(${scale})`,
				easing: 'ease-in',
				offset: 0.35,
			},
			{
				transform: `translateX(${x}px) translateY(400px) scale(${scale})`,
				offset: 1,
			},
		];
		const animation = this.el.animate(keyframes, {
			duration: 700,
			fill: 'forwards',
		});
		animation.commitStyles();
		return animation;
	}

	xray(creatureId: number) {
		if (creatureId === this.creature.id) {
			this.el.classList.add('xray');
		} else {
			this.el.classList.remove('xray');
		}
	}

	bounce(creatureId: number, i: number, x: number, bounceHeight: number) {
		if (creatureId === this.creature.id) {
			this.animateBounce(i, x, bounceHeight);
		}
	}

	addEvents() {
		const el = this.el;
		const h = this.eventHandlers;

		el.addEventListener('click', () => {
			if (h.onCreatureClick) h.onCreatureClick(this.creature);
		});

		el.addEventListener('contextmenu', (event) => {
			event.preventDefault();
			event.stopPropagation();
			if (h.onCreatureClick) h.onCreatureClick(this.creature);
		});

		el.addEventListener('mouseenter', () => {
			if (h.onCreatureMouseEnter) h.onCreatureMouseEnter(this.creature);
		});

		el.addEventListener('mouseleave', () => {
			if (h.onCreatureMouseLeave) h.onCreatureMouseLeave(this.creature);
		});
	}

	refresh() {
		this.updateDOM();
	}

	getWidth() {
		return this.isActiveCreature ? 100 : this.getQueuedWidth();
	}

	getQueuedWidth() {
		if (window.matchMedia('(orientation: landscape) and (max-height: 512px)').matches) {
			return window.matchMedia('(max-height: 319px)').matches ? 56 : 64;
		}
		return 80;
	}

	static is(obj: object) {
		return typeof obj !== 'undefined' && CreatureVignette.prototype.isPrototypeOf(obj);
	}
}

class TurnEndMarkerVignette extends Vignette {
	constructor(turnNumber: number, eventHandlers: QueueEventHandlers) {
		super();
		this.turnNumber = turnNumber;
		this.eventHandlers = eventHandlers;
	}

	getHash() {
		return ['turnend', 'turn' + this.turnNumber].join('_');
	}

	getHTML() {
		return `<div turn="${this.turnNumber}" roundmarker="1" class="vignette roundmarker">
			<div class="frame"></div>
            <div class="stats">Round ${this.turnNumber}</div>
		</div>`;
	}

	animateInsert(queuePosition: number, x: number) {
		const enlarged = queuePosition === 0;
		const scale = enlarged ? 100 / this.getIconWidth() : 1;
		const y = enlarged ? 20 + this.getIconWidth() * (1 - scale) : 0;
		this.el.classList.toggle('active', enlarged);
		const animation = this.el.animate(
			[
				{
					transform: `translateX(${x + 500}px) translateY(${y - 100}px) scale(${scale})`,
					easing: 'ease-out',
				},
				{
					transform: `translateX(${x + 500}px) translateY(${y}px) scale(${scale})`,
					easing: 'ease-in',
					offset: 0.3,
				},
				{ transform: `translateX(${x}px) translateY(${y}px) scale(${scale})` },
			],
			{ duration: CONST.animDurationMS, fill: 'forwards' },
		);
		animation.commitStyles();
		return animation;
	}

	animateUpdate(queuePosition: number, x: number) {
		const enlarged = queuePosition === 0;
		const scale = enlarged ? 100 / this.getIconWidth() : 1;
		this.el.classList.toggle('active', enlarged);
		const y = enlarged ? 20 + this.getIconWidth() * (1 - scale) : 0;
		const keyframes = [{ transform: `translateX(${x}px) translateY(${y}px) scale(${scale})` }];
		const animation = this.el.animate(keyframes, {
			duration: CONST.animDurationMS,
			fill: 'forwards',
		});
		animation.commitStyles();
		return animation;
	}

	animateDeleteFromFront(queuePosition: number, x: number, emptySpaceAtFrontOfQueue: number) {
		const width = this.getIconWidth();
		const scale = 100 / width;
		this.el.classList.add('active');
		// The active marker has no label: anchor the icon itself to the bottom.
		const y = 20 + width * (1 - scale);
		const approachDuration = queuePosition === 0 ? 0 : CONST.animDurationMS;
		const duration = approachDuration + CONST.animDurationMS;
		const cornerOffset = approachDuration / duration;
		const target = {
			transform: `translateX(-100px) translateY(${y}px) scale(${scale})`,
			offset: 1,
		};
		// Share the following avatar's approach and departure timing, keeping their edges together.
		const keyframes =
			approachDuration > 0
				? [
						{ transform: `translateX(${x}px) translateY(0px) scale(1)`, offset: 0 },
						{
							transform: `translateX(${
								(emptySpaceAtFrontOfQueue - 100) * 0.7
							}px) translateY(${y}px) scale(${scale})`,
							offset: cornerOffset * 0.3,
						},
						{
							transform: `translateX(0px) translateY(${y}px) scale(${scale})`,
							offset: cornerOffset,
						},
						target,
				  ]
				: [target];
		const animation = this.el.animate(keyframes, {
			duration,
			fill: 'forwards',
		});
		animation.commitStyles();
		return animation;
	}

	addEvents() {
		const el = this.el;
		const h = this.eventHandlers;

		el.addEventListener('mousedown', (event: MouseEvent) => {
			if (event.button !== 0 && event.button !== 1) {
				return;
			}
			event.preventDefault();
			event.stopPropagation();
			if (h.onTurnEndMarkerMouseDown) {
				h.onTurnEndMarkerMouseDown(event.button, this.turnNumber);
			}
		});

		el.addEventListener('contextmenu', (event: MouseEvent) => {
			event.preventDefault();
			event.stopPropagation();
			if (h.onTurnEndMarkerMouseDown) {
				h.onTurnEndMarkerMouseDown(event.button, this.turnNumber);
			}
		});

		el.addEventListener('mouseenter', () => {
			if (h.onTurnEndMouseEnter) h.onTurnEndMouseEnter(this.turnNumber);
		});

		el.addEventListener('mouseleave', () => {
			if (h.onTurnEndMouseLeave) h.onTurnEndMouseLeave(this.turnNumber);
		});
	}

	getWidth() {
		return this.el?.classList.contains('active') ? 100 : this.getIconWidth();
	}

	private getIconWidth() {
		if (window.matchMedia('(orientation: landscape) and (max-height: 512px)').matches) {
			return window.matchMedia('(max-height: 319px)').matches ? 56 : 64;
		}
		return 80;
	}

	static is(obj: object) {
		return typeof obj !== 'undefined' && TurnEndMarkerVignette.prototype.isPrototypeOf(obj);
	}
}

class DelayMarkerVignette extends Vignette {
	constructor(turnNumber: number, eventHandlers: QueueEventHandlers) {
		super();
		this.turnNumber = turnNumber;
		this.eventHandlers = eventHandlers;
	}

	getHTML() {
		return `<div class="vignette delaymarker">
			<div class="frame"></div>
            <div class="stats">Delayed</div>
		</div>`;
	}

	getHash() {
		return ['delay', 'turn' + this.turnNumber].join('_');
	}

	addEvents() {
		const el = this.el;
		const h = this.eventHandlers;

		el.addEventListener('click', () => {
			if (h.onDelayClick) h.onDelayClick();
		});

		el.addEventListener('mouseenter', () => {
			if (h.onDelayMouseEnter) h.onDelayMouseEnter();
		});

		el.addEventListener('mouseleave', () => {
			if (h.onDelayMouseLeave) h.onDelayMouseLeave();
		});
	}

	animateInsert(queuePosition: number, x: number) {
		const keyframes = [
			{
				transform: `translateX(${x}px) translateY(-100px) scale(1)`,
			},
			{
				transform: `translateX(${x}px) translateY(-100px) scale(1)`,
				easing: 'ease-out',
			},
			{ transform: `translateX(${x}px) translateY(0px) scale(1)` },
		];
		const animation = this.el.animate(keyframes, {
			duration: CONST.animDurationMS * 2,
			fill: 'forwards',
		});
		animation.commitStyles();
		return animation;
	}
}

class EventVignette extends Vignette {
	event: QueueEvent;
	isActive: boolean;

	constructor(event: QueueEvent, eventHandlers: QueueEventHandlers, isActive: boolean) {
		super();
		this.event = event;
		this.turnNumber = event.turn;
		this.eventHandlers = eventHandlers;
		this.isActive = isActive;
	}

	getHash() {
		return ['event', this.event.id, 'turn' + this.turnNumber].join('_');
	}

	getHTML() {
		const data =
			this.event.type === 'crashing-globe'
				? (this.event.data as { attacker: Creature; upgraded: boolean })
				: undefined;
		const title = data?.upgraded ? 'Crashing Globe (upgraded)' : this.event.title;
		const classes = [
			'vignette',
			'event',
			this.event.type,
			data ? 'crashing-globe-ability' : '',
			data ? 'p' + data.attacker.team : '',
			this.isActive ? 'active' : '',
		].join(' ');
		if (data) {
			return `<div class="${classes}">
				<div class="crashing-globe-bg"></div>
				<div class="crashing-globe-icon"></div>
				<div class="frame p${data.attacker.team}"></div>
				<div class="overlay_frame"></div>
				<div class="stats">${title}</div>
			</div>`;
		}
		return `<div class="${classes}">
				<div class="frame"></div>
				<div class="overlay_frame"></div>
				<div class="stats">${title}</div>
			</div>`;
	}

	insert(containerElement: HTMLElement, queuePosition: number, x: number) {
		super.insert(containerElement, queuePosition, x);
		this.updateDOM();
		return this;
	}

	update(queuePosition: number, x: number) {
		this.queuePosition = queuePosition;
		this.xPosition = x;
		this.updateDOM();
		this.animateUpdate(queuePosition, x);
		return this;
	}

	addEvents() {
		if (this.event.type !== 'crashing-globe') {
			return;
		}

		this.el.addEventListener('contextmenu', (event: MouseEvent) => {
			event.preventDefault();
			event.stopPropagation();
			const data = this.event.data as { attacker: Creature };
			this.eventHandlers.onEventContextMenu?.(data.attacker);
		});
	}

	private updateDOM() {
		this.el.classList.toggle('active', this.isActive);
		this.el.classList.toggle('delayed', Boolean(this.event.delayed));
		if (this.event.type === 'crashing-globe') {
			const data = this.event.data as { attacker: Creature; upgraded: boolean };
			const classes = this.el.classList;
			classes.add('crashing-globe-ability', 'p' + data.attacker.team);
			classes.toggle('upgraded', data.upgraded);
			const iconEl = this.el.querySelector('.crashing-globe-icon') as HTMLElement | null;
			if (iconEl) {
				iconEl.style.backgroundImage = `url('${getUrl('units/abilities/Asher 3')}')`;
				iconEl.style.display = '';
			}
			const bgEl = this.el.querySelector('.crashing-globe-bg') as HTMLElement | null;
			if (bgEl) {
				bgEl.style.backgroundColor = 'rgba(0, 0, 0, 0.85)';
			}
		}
	}

	getWidth() {
		return 80;
	}
}

const utils = {
	arrToDict: (arr: Vignette[], keyFn: (arg0: Vignette) => string) => {
		// NOTE: Turns an array to an object using the key function.
		// If the keyFn produces two or more identical keys, only the
		// last instance at that key will be kept.
		const result = {};
		for (const element of arr) {
			result[keyFn(element)] = element;
		}
		return result;
	},

	takeWhile: (arr: Vignette[], takeFn: (arg0: Vignette) => boolean) => {
		const result = [];
		for (const element of arr) {
			if (!takeFn(element)) {
				break;
			}
			result.push(element);
		}
		return result;
	},

	findLastIndex: (arr: Vignette[], findFn: (arg0: Vignette) => boolean) => {
		for (let i = arr.length - 1; i >= 0; i--) {
			if (findFn(arr[i])) {
				return i;
			}
		}
		return -1;
	},

	splitSetBy: (
		s: Set<string>,
		splitFn: (value: string, key: string, set: Set<string>) => boolean,
	) => {
		const a = new Set();
		const b = new Set();
		s.forEach((value, key, set) => {
			if (splitFn(value, key, set)) {
				a.add(value);
			} else {
				b.add(value);
			}
		});
		return [a, b];
	},

	toClassName: (s = '', ifNone = 'none', prefixIfNumeric = 'class_') => {
		const SEP = '_';
		s = (SEP + s + SEP).toLowerCase().replace(/[^a-z0-9]+/g, SEP);
		s = s.substring(1, s.length - 1);

		if (s === '' || s === SEP) {
			return ifNone;
		} else if ('0123456789'.indexOf(s[0]) !== -1) {
			return prefixIfNumeric + s;
		}
		return s;
	},
};

type QueueEventHandlers = {
	onCreatureClick?: (creature: Creature) => void;
	onEventContextMenu?: (creature: Creature) => void;
	onCreatureMouseEnter?: (creature: Creature) => void;
	onCreatureMouseLeave?: (creature: Creature) => void;
	onDelayClick?: () => void;
	onDelayMouseEnter?: () => void;
	onDelayMouseLeave?: () => void;
	onTurnEndClick?: (turnNumber: number) => void;
	onTurnEndMarkerMouseDown?: (button: number, turnNumber: number) => void;
	onTurnEndMouseEnter?: (turnNumber: number) => void;
	onTurnEndMouseLeave?: (turnNumber: number) => void;
};
